class RegisterBody(BaseModel):
    name: str = Field(min_length=2, max_length=120)
    phone: str = Field(min_length=7, max_length=24)
    password: str = Field(min_length=10, max_length=128)


class LoginBody(BaseModel):
    phone: str = Field(min_length=7, max_length=24)
    password: str = Field(min_length=1, max_length=128)


class DecisionBody(BaseModel):
    approve: bool


class PdfBody(BaseModel):
    case_number: str = Field(min_length=1, max_length=40)


def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


@contextmanager
def _db():
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(DB_PATH, timeout=20)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys=ON")
    try:
        yield connection
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()


def _normalize_phone(value: str) -> str:
    normalized = []
    for char in value.strip():
        if char.isdecimal():
            normalized.append(str(unicodedata.decimal(char)))
        elif char == "+" and not normalized:
            normalized.append(char)
        elif char in " -().":
            continue
        else:
            raise HTTPException(422, "رقم الجوال غير صالح.")
    value = "".join(normalized)
    digits = value[1:] if value.startswith("+") else value
    if not digits.isdigit() or not 7 <= len(digits) <= 15:
        raise HTTPException(422, "رقم الجوال غير صالح.")
    return value


def _audit(actor_id: int | None, action: str, *, target_id: int | None = None, metadata=None):
    # Never include passwords, full case data, or search text in audit metadata.
    with _db() as connection:
        connection.execute(
            "INSERT INTO activity(actor_id, action, target_id, metadata_json, created_at) VALUES(?,?,?,?,?)",
            (actor_id, action, target_id, json.dumps(metadata or {}, ensure_ascii=False), _now()),
        )


def _initialize_database():
    with _db() as connection:
        connection.executescript("""
            CREATE TABLE IF NOT EXISTS users(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                phone TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),
                state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')),
                created_at TEXT NOT NULL,
                reviewed_at TEXT,
                reviewed_by INTEGER REFERENCES users(id)
            );
            CREATE TABLE IF NOT EXISTS activity(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                actor_id INTEGER REFERENCES users(id),
                action TEXT NOT NULL,
                target_id INTEGER REFERENCES users(id),
                metadata_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_users_state ON users(state, created_at);
            CREATE INDEX IF NOT EXISTS idx_activity_created ON activity(id DESC);
            CREATE INDEX IF NOT EXISTS idx_activity_actor ON activity(actor_id, id DESC);
        """)
        if connection.execute("SELECT 1 FROM users WHERE role='admin' LIMIT 1").fetchone() is None:
            name = os.getenv("ADMIN_BOOTSTRAP_NAME", "").strip()
            phone = os.getenv("ADMIN_BOOTSTRAP_PHONE", "").strip()
            password = os.getenv("ADMIN_BOOTSTRAP_PASSWORD", "")
            if not name or not phone or len(password) < 12:
                raise RuntimeError("Set ADMIN_BOOTSTRAP_NAME, ADMIN_BOOTSTRAP_PHONE and a 12+ character ADMIN_BOOTSTRAP_PASSWORD for first startup.")
            connection.execute(
                "INSERT INTO users(name,phone,password_hash,role,state,created_at) VALUES(?,?,?,'admin','approved',?)",
                (name, _normalize_phone(phone), HASHER.hash(password), _now()),
            )
            LOGGER.info("Initial administrator created; credentials are not logged.")


@app.on_event("startup")
def startup():
    if len(os.getenv("JWT_SECRET", "")) < 32:
        raise RuntimeError("JWT_SECRET must be a random value of at least 32 characters.")
    _initialize_database()


@app.middleware("http")
async def secure_headers(request: Request, call_next):
    response = await call_next(request)
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    return response


def _public_user(user) -> dict:
    return {key: user[key] for key in ("id", "name", "phone", "role", "state", "created_at")}


def _current_user(credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(BEARER)]):
    if credentials is None:
        raise HTTPException(401, "سجّل الدخول للمتابعة.", headers={"WWW-Authenticate": "Bearer"})
    try:
        claims = jwt.decode(
            credentials.credentials,
            os.environ["JWT_SECRET"],
            algorithms=["HS256"],
            options={"require": ["sub", "exp"]},
        )
        user_id = int(claims["sub"])
    except (jwt.PyJWTError, KeyError, TypeError, ValueError):
        raise HTTPException(401, "انتهت صلاحية الجلسة؛ سجّل الدخول مجدداً.")
    with _db() as connection:
        user = connection.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone()
    if user is None:
        raise HTTPException(401, "الحساب غير موجود.")
    if user["state"] != "approved":
        raise HTTPException(403, "الحساب غير معتمد أو تم إيقافه.")
    return dict(user)


def _admin_user(user: Annotated[dict, Depends(_current_user)]):
    if user["role"] != "admin":
        raise HTTPException(403, "هذه الصفحة متاحة لمدير النظام فقط.")
    return user


def _token(user) -> str:
    timestamp = int(datetime.now(timezone.utc).timestamp())
    return jwt.encode(
        {"sub": str(user["id"]), "iat": timestamp, "exp": timestamp + TOKEN_TTL_SECONDS},
        os.environ["JWT_SECRET"], algorithm="HS256",
    )


