    except sqlite3.IntegrityError:
        raise HTTPException(409, "رقم الجوال مسجل مسبقاً.")
    return {"state": "pending", "message": "تم استلام طلبك. يمكنك الدخول بعد موافقة مدير النظام."}


@app.post("/api/auth/login")
def login(body: LoginBody):
    phone = _normalize_phone(body.phone)
    with _db() as connection:
        user = connection.execute("SELECT * FROM users WHERE phone=?", (phone,)).fetchone()
    try:
        valid = HASHER.verify(user["password_hash"] if user else DUMMY_HASH, body.password)
    except (VerifyMismatchError, InvalidHashError):
