    normalized = "".join(str(unicodedata.decimal(c)) if c.isdecimal() else c for c in value.strip())
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d/%m/%Y"):
        try:
            return datetime.strptime(normalized, fmt).date().isoformat()
        except ValueError:
