{"branch":"main","files":[{"content":""""Private API for the Albayda Court Android client.

Case data and PDF generation are delegated to the existing case_records module.
The activity log is deliberately restricted to approved administrator accounts.
"""
from __future__ import annotations

import json
import logging
import os
import re
import sqlite3
import unicodedata
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Annotated

import jwt
from argon2 import PasswordHasher
from argon2.exceptions import InvalidHashError, VerifyMismatchError
from fastapi import Depends, FastAPI, HTTPException, Query, Request, Response
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from pydantic import BaseModel, Field

from case_records import (
    CaseRecordsError,
    available_case_types,
    available_judges,
    generate_case_pdf,
    generate_sessions_pdf,
    load_case_records,
    normalize_judge_name,
    search_case_records,
    search_sessions_by_date,
)

logging.basicConfig(level=os.getenv("LOG_LEVEL", "INFO"))
LOGGER = logging.getLogger("albayda_api")
DB_PATH = Path(os.getenv("APP_DATABASE_PATH", "./data/app.sqlite3"))
HASHER = PasswordHasher()
DUMMY_HASH = HASHER.hash("constant-time-dummy-password")
BEARER = HTTPBearer(auto_error=False)
TOKEN_TTL_SECONDS = 8 * 60 * 60
app = FastAPI(title="Albayda Court API", version="1.0.0", docs_url=None, redoc_url=None)


class RegisterBody(BaseModel):
    name: str = Field(min_length=2, max_length=120)
    phone: str = Field(min_length=7, max_length=24)
    password: str = Field(min_length=10, max_length=128)


class LoginBody(BaseModel):
    phone: str = Field(min_length=7, max_length=24)
    password: str = Field(min_length=1, max_length=128)


class DecisionBody(BaseModel):
    approve: bool


class PdfBody(BaseModel):
    case_number: str = Field(min_length=1, max_length=40)


def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


@contextmanager
def _db():
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(DB_PATH, timeout=20)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys=ON")
    try:
        yield connection
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()


def _normalize_phone(value: str) -> str:
    normalized = []
    for char in value.strip():
        if char.isdecimal():
            normalized.append(str(unicodedata.decimal(char)))
        elif char == "+" and not normalized:
            normalized.append(char)
        elif char in " -().":
            continue
        else:
            raise HTTPException(422, "رقم الجوال غير صالح.")
    value = "".join(normalized)
    digits = value[1:] if value.startswith("+") else value
    if not digits.isdigit() or not 7 <= len(digits) <= 15:
        raise HTTPException(422, "رقم الجوال غير صالح.")
    return value


def _audit(actor_id: int | None, action: str, *, target_id: int | None = None, metadata=None):
    # Never include passwords, full case data, or search text in audit metadata.
    with _db() as connection:
        connection.execute(
            "INSERT INTO activity(actor_id, action, target_id, metadata_json, created_at) VALUES(?,?,?,?,?)",
            (actor_id, action, target_id, json.dumps(metadata or {}, ensure_ascii=False), _now()),
        )


def _initialize_database():
    with _db() as connection:
        connection.executescript("""
            CREATE TABLE IF NOT EXISTS users(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                phone TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),
                state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')),
                created_at TEXT NOT NULL,
                reviewed_at TEXT,
                reviewed_by INTEGER REFERENCES users(id)
            );
            CREATE TABLE IF NOT EXISTS activity(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                actor_id INTEGER REFERENCES users(id),
                action TEXT NOT NULL,
                target_id INTEGER REFERENCES users(id),
                metadata_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_users_state ON users(state, created_at);
            CREATE INDEX IF NOT EXISTS idx_activity_created ON activity(id DESC);
            CREATE INDEX IF NOT EXISTS idx_activity_actor ON activity(actor_id, id DESC);
        """)
        if connection.execute("SELECT 1 FROM users WHERE role='admin' LIMIT 1").fetchone() is None:
            name = os.getenv("ADMIN_BOOTSTRAP_NAME", "").strip()
            phone = os.getenv("ADMIN_BOOTSTRAP_PHONE", "").strip()
            password = os.getenv("ADMIN_BOOTSTRAP_PASSWORD", "")
            if not name or not phone or len(password) < 12:
                raise RuntimeError("Set ADMIN_BOOTSTRAP_NAME, ADMIN_BOOTSTRAP_PHONE and a 12+ character ADMIN_BOOTSTRAP_PASSWORD for first startup.")
            connection.execute(
                "INSERT INTO users(name,phone,password_hash,role,state,created_at) VALUES(?,?,?,'admin','approved',?)",
                (name, _normalize_phone(phone), HASHER.hash(password), _now()),
            )
            LOGGER.info("Initial administrator created; credentials are not logged.")


@app.on_event("startup")
def startup():
    if len(os.getenv("JWT_SECRET", "")) < 32:
        raise RuntimeError("JWT_SECRET must be a random value of at least 32 characters.")
    _initialize_database()


@app.middleware("http")
async def secure_headers(request: Request, call_next):
    response = await call_next(request)
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    return response


def _public_user(user) -> dict:
    return {key: user[key] for key in ("id", "name", "phone", "role", "state", "created_at")}


def _current_user(credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(BEARER)]):
    if credentials is None:
        raise HTTPException(401, "سجّل الدخول للمتابعة.", headers={"WWW-Authenticate": "Bearer"})
    try:
        claims = jwt.decode(
            credentials.credentials,
            os.environ["JWT_SECRET"],
            algorithms=["HS256"],
            options={"require": ["sub", "exp"]},
        )
        user_id = int(claims["sub"])
    except (jwt.PyJWTError, KeyError, TypeError, ValueError):
        raise HTTPException(401, "انتهت صلاحية الجلسة؛ سجّل الدخول مجدداً.")
    with _db() as connection:
        user = connection.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone()
    if user is None:
        raise HTTPException(401, "الحساب غير موجود.")
    if user["state"] != "approved":
        raise HTTPException(403, "الحساب غير معتمد أو تم إيقافه.")
    return dict(user)


def _admin_user(user: Annotated[dict, Depends(_current_user)]):
    if user["role"] != "admin":
        raise HTTPException(403, "هذه الصفحة متاحة لمدير النظام فقط.")
    return user


def _token(user) -> str:
    timestamp = int(datetime.now(timezone.utc).timestamp())
    return jwt.encode(
        {"sub": str(user["id"]), "iat": timestamp, "exp": timestamp + TOKEN_TTL_SECONDS},
        os.environ["JWT_SECRET"], algorithm="HS256",
    )


@app.get("/api/health")
def health():
    return {"status": "ok"}


@app.post("/api/auth/register", status_code=202)
def register(body: RegisterBody):
    name = body.name.strip()
    if len(name) < 2:
        raise HTTPException(422, "أدخل الاسم كاملاً.")
    phone = _normalize_phone(body.phone)
    try:
        with _db() as connection:
            cursor = connection.execute(
                "INSERT INTO users(name,phone,password_hash,state,created_at) VALUES(?,?,?,'pending',?)",
                (name, phone, HASHER.hash(body.password), _now()),
            )
            user_id = cursor.lastrowid
            connection.execute(
                "INSERT INTO activity(actor_id,action,target_id,created_at) VALUES(?,?,?,?)",
                (user_id, "registration_submitted", user_id, _now()),
            )
    except sqlite3.IntegrityError:
        raise HTTPException(409, "رقم الجوال مسجل مسبقاً.")
    return {"state": "pending", "message": "تم استلام طلبك. يمكنك الدخول بعد موافقة مدير النظام."}


@app.post("/api/auth/login")
def login(body: LoginBody):
    phone = _normalize_phone(body.phone)
    with _db() as connection:
        user = connection.execute("SELECT * FROM users WHERE phone=?", (phone,)).fetchone()
    try:
        valid = HASHER.verify(user["password_hash"] if user else DUMMY_HASH, body.password)
    except (VerifyMismatchError, InvalidHashError):
        valid = False
    if not valid:
        _audit(None, "login_failed")
        raise HTTPException(401, "رقم الجوال أو كلمة المرور غير صحيحة.")
    if user["state"] != "approved":
        _audit(user["id"], "login_denied_unapproved")
        raise HTTPException(403, "طلب الحساب بانتظار مراجعة مدير النظام.")
    _audit(user["id"], "login_succeeded")
    return {"access_token": _token(user), "token_type": "bearer", "user": _public_user(user)}


@app.get("/api/me")
def me(user: Annotated[dict, Depends(_current_user)]):
    return _public_user(user)


@app.get("/api/case-types")
def case_types(user: Annotated[dict, Depends(_current_user)]):
    try:
        records = load_case_records()
    except CaseRecordsError as exc:
        raise HTTPException(503, str(exc))
    _audit(user["id"], "case_types_viewed")
    return {"case_types": available_case_types(records), "judges": available_judges(records)}


@app.get("/api/cases/search")
def search_cases(
    user: Annotated[dict, Depends(_current_user)],
    q: str = Query(min_length=1, max_length=120),
    case_type: str = Query(default="all", max_length=80),
    judge: str = Query(default="all", max_length=120),
    limit: int = Query(default=20, ge=1, le=50),
):
    query = q.strip()
    if not query:
        raise HTTPException(422, "أدخل رقم القضية أو اسم أحد الأطراف.")
    method = "number" if "/" in query else "name"
    try:
        results = search_case_records(load_case_records(), query, method, case_type, judge, limit=limit)
    except CaseRecordsError as exc:
        raise HTTPException(503, str(exc))
    _audit(user["id"], "case_search", metadata={"method": method, "result_count": len(results)})
    return {"count": len(results), "cases": results}


def _normalize_date(value: str):
    normalized = "".join(str(unicodedata.decimal(c)) if c.isdecimal() else c for c in value.strip())
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d/%m/%Y"):
        try:
            return datetime.strptime(normalized, fmt).date().isoformat()
        except ValueError:
            pass
    return None


@app.get("/api/sessions")
def sessions(
    user: Annotated[dict, Depends(_current_user)],
    sitting_date: str = Query(alias="date", min_length=8, max_length=10),
    judge: str = Query(default="all", max_length=120),
):
    normalized = _normalize_date(sitting_date)
    if normalized is None:
        raise HTTPException(422, "التاريخ غير صالح؛ استخدم YYYY-MM-DD.")
    try:
        results = search_sessions_by_date(load_case_records(), normalized)
    except CaseRecordsError as exc:
        raise HTTPException(503, str(exc))
    if judge != "all":
        results = [r for r in results if normalize_judge_name(r.get("برئاسة القاضي")) == normalize_judge_name(judge)]
    _audit(user["id"], "sessions_search", metadata={"result_count": len(results)})
    return {"date": normalized, "count": len(results), "sessions": results[:500]}


@app.post("/api/cases/pdf")
def case_pdf(body: PdfBody, user: Annotated[dict, Depends(_current_user)]):
    try:
        results = search_case_records(load_case_records(), body.case_number, "number", limit=1)
        if not results:
            raise HTTPException(404, "لم يتم العثور على القضية.")
        pdf = generate_case_pdf(results[0])
    except CaseRecordsError as exc:
        raise HTTPException(503, str(exc))
    safe_number = re.sub(r"[^0-9A-Za-z_-]", "_", body.case_number)[:40] or "case"
    _audit(user["id"], "case_pdf_downloaded")
    return Response(pdf.getvalue(), media_type="application/pdf", headers={"Content-Disposition": f'attachment; filename="case_{safe_number}.pdf"'})


@app.get("/api/admin/users")
def admin_users(
    admin: Annotated[dict, Depends(_admin_user)],
    state: str = Query(default="pending", pattern="^(pending|approved|rejected|all)$"),
):
    with _db() as connection:
        if state == "all":
            users = connection.execute("SELECT * FROM users ORDER BY created_at DESC LIMIT 500").fetchall()
        else:
            users = connection.execute("SELECT * FROM users WHERE state=? ORDER BY created_at DESC LIMIT 500", (state,)).fetchall()
    _audit(admin["id"], "admin_users_listed", metadata={"filter": state})
    return {"users": [_public_user(user) for user in users]}


@app.post("/api/admin/users/{user_id}/decision")
def decide_user(user_id: int, body: DecisionBody, admin: Annotated[dict, Depends(_admin_user)]):
    new_state = "approved" if body.approve else "rejected"
    with _db() as connection:
        target = connection.execute("SELECT id,role FROM users WHERE id=?", (user_id,)).fetchone()
        if target is None:
            raise HTTPException(404, "الحساب غير موجود.")
        if target["role"] == "admin":
            raise HTTPException(409, "لا يمكن تغيير حالة حساب مدير النظام من هنا.")
        connection.execute("UPDATE users SET state=?,reviewed_at=?,reviewed_by=? WHERE id=?", (new_state, _now(), admin["id"], user_id))
        connection.execute("INSERT INTO activity(actor_id,action,target_id,created_at) VALUES(?,?,?,?)", (admin["id"], "user_" + new_state, user_id, _now()))
    return {"id": user_id, "state": new_state}


@app.get("/api/admin/activity")
def admin_activity(
    admin: Annotated[dict, Depends(_admin_user)],
    limit: int = Query(default=100, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
):
