private data class CourtCase(val raw: JSONObject) {
    val number get() = raw.optString("رقم القضية", "—")
    val type get() = raw.optString("نوع القضية", "")
    val plaintiff get() = raw.optString("المدعي", "")
    val defendant get() = raw.optString("المدعى عليه", "")
    val judge get() = raw.optString("برئاسة القاضي", "")
    val nextSession get() = raw.optString("الجلسة القادمة", "")
    val subject get() = raw.optString("موضوعها", "")
}
private data class CourtUser(val id: Int, val name: String, val phone: String, val state: String)
private data class ActivityItem(val name: String, val phone: String, val action: String, val timestamp: String)

@Composable
private fun CourtApp() {
    val scope = rememberCoroutineScope()
    var token by remember { mutableStateOf<String?>(null) }
    var role by remember { mutableStateOf("user") }
    var displayName by remember { mutableStateOf("") }
    var screen by remember { mutableStateOf("auth") }
    var isRegistration by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var query by remember { mutableStateOf("") }
    var selectedDate by remember { mutableStateOf("") }
    var cases by remember { mutableStateOf(emptyList<CourtCase>()) }
    var sessions by remember { mutableStateOf(emptyList<CourtCase>()) }
    var pendingUsers by remember { mutableStateOf(emptyList<CourtUser>()) }
    var activities by remember { mutableStateOf(emptyList<ActivityItem>()) }
    var message by remember { mutableStateOf("") }
    var busy by remember { mutableStateOf(false) }

    fun request(block: suspend () -> Unit) {
        if (busy) return
        busy = true
        message = ""
        scope.launch {
            try { withContext(Dispatchers.IO) { block() } }
            catch (e: Exception) { message = e.message ?: "تعذر الاتصال بالخادم." }
            finally { busy = false }
        }
    }

    Surface(Modifier.fillMaxSize(), color = Canvas) {
        when (screen) {
            "auth" -> AuthScreen(
                registering = isRegistration, name = name, phone = phone, password = password,
                busy = busy, message = message,
                onName = { name = it }, onPhone = { phone = it }, onPassword = { password = it },
                onToggle = { isRegistration = !isRegistration; message = "" },
                onSubmit = {
                    request {
                        if (isRegistration) {
                            val result = Api.register(name, phone, password)
                            message = result.optString("message", "تم إرسال طلب التسجيل للمسؤول.")
                            isRegistration = false
                            password = ""
                        } else {
                            val result = Api.login(phone, password)
                            token = result.getString("access_token")
                            val user = result.getJSONObject("user")
                            role = user.optString("role", "user")
                            displayName = user.optString("name")
                            password = ""
                            screen = "home"
                        }
                    }
                },
            )
            "home" -> HomeScreen(
                name = displayName, role = role, query = query, cases = cases, busy = busy, message = message,
                onQuery = { query = it },
                onSearch = { request { cases = Api.search(token!!, query).map(::CourtCase) } },
                onSessions = { screen = "sessions" },
                onAdmin = { screen = "admin" },
                onLogout = { token = null; role = "user"; cases = emptyList(); screen = "auth"; message = "تم تسجيل الخروج" },
            )
            "sessions" -> SessionsScreen(
                date = selectedDate, sessions = sessions, busy = busy, message = message,
                onDate = { selectedDate = it }, onBack = { screen = "home" },
                onSearch = { request { sessions = Api.sessions(token!!, selectedDate).map(::CourtCase) } },
            )
            "admin" -> AdminScreen(
                users = pendingUsers, activity = activities, busy = busy, message = message,
                onBack = { screen = "home" },
                onLoadUsers = { request { pendingUsers = Api.pending(token!!) } },
                onLoadActivity = { request { activities = Api.activity(token!!) } },
                onDecision = { user, approve -> request { Api.decide(token!!, user.id, approve); pendingUsers = Api.pending(token!!) } },
            )
        }
    }
}

