private object Api {
    private val client = OkHttpClient.Builder().callTimeout(java.time.Duration.ofSeconds(30)).build()
    private val jsonType = "application/json; charset=utf-8".toMediaType()
    private fun base(): String {
        val value = BuildConfig.API_BASE_URL.trim().trimEnd('/')
        check(value.startsWith("https://") && !value.contains("example.invalid")) { "عنوان الخادم غير مضبوط. يلزم API_BASE_URL حقيقي وآمن HTTPS." }
        return value
    }
    private fun call(path: String, method: String = "GET", body: JSONObject? = null, token: String? = null): String {
        val builder = Request.Builder().url(base() + path).header("Accept", "application/json")
        if (token != null) builder.header("Authorization", "Bearer $token")
        val requestBody = body?.toString()?.toRequestBody(jsonType)
        if (method == "POST") builder.post(requestBody ?: "{}".toRequestBody(jsonType)) else builder.get()
        client.newCall(builder.build()).execute().use { response ->
            val text = response.body?.string().orEmpty()
            if (!response.isSuccessful) {
                val detail = try { JSONObject(text).optString("detail") } catch (_: Exception) { "" }
                error(detail.ifBlank { "فشل الطلب (${response.code})." })
            }
            return text
        }
    }
    fun register(name: String, phone: String, password: String) = JSONObject(call("/api/auth/register", "POST", JSONObject().put("name", name).put("phone", phone).put("password", password)))
    fun login(phone: String, password: String) = JSONObject(call("/api/auth/login", "POST", JSONObject().put("phone", phone).put("password", password)))
    fun search(token: String, query: String): List<JSONObject> {
        val encoded = URLEncoder.encode(query, "UTF-8")
        val array = JSONObject(call("/api/cases/search?q=$encoded&limit=30", token = token)).getJSONArray("cases")
        return (0 until array.length()).map { array.getJSONObject(it) }
    }
    fun sessions(token: String, date: String): List<JSONObject> {
        val encoded = URLEncoder.encode(date, "UTF-8")
        val array = JSONObject(call("/api/sessions?date=$encoded", token = token)).getJSONArray("sessions")
        return (0 until array.length()).map { array.getJSONObject(it) }
    }
    fun pending(token: String): List<CourtUser> {
        val array = JSONObject(call("/api/admin/users?state=pending", token = token)).getJSONArray("users")
        return (0 until array.length()).map { val u = array.getJSONObject(it); CourtUser(u.getInt("id"), u.optString("name"), u.optString("phone"), u.optString("state")) }
    }
    fun decide(token: String, userId: Int, approve: Boolean) { call("/api/admin/users/$userId/decision", "POST", JSONObject().put("approve", approve), token) }
    fun activity(token: String): List<ActivityItem> {
        val array = JSONObject(call("/api/admin/activity?limit=150", token = token)).getJSONArray("events")
        return (0 until array.length()).map { i ->
            val e = array.getJSONObject(i); val actor = e.optJSONObject("actor")
            ActivityItem(actor?.optString("name").orEmpty(), actor?.optString("phone").orEmpty(), e.optString("action"), e.optString("created_at"))
        }
    }
}
