private val Navy = Color(0xFF203D52)
private val NavyDark = Color(0xFF173247)
private val Gold = Color(0xFFC9A044)
private val Page = Color(0xFFF6F6F4)
private val Muted = Color(0xFF7B858A)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.statusBarColor = android.graphics.Color.rgb(246, 246, 244)
        window.navigationBarColor = android.graphics.Color.rgb(246, 246, 244)
        window.decorView.systemUiVisibility = android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR or android.view.View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR
        setContent { CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) { CourtTheme { CourtApp() } } }
    }
}

@Composable
private fun CourtTheme(content: @Composable () -> Unit) {
    MaterialTheme(colorScheme = lightColorScheme(primary = Navy, secondary = Gold, background = Page, surface = Color.White, onPrimary = Color.White, onSurface = Navy), content = content)
}

private data class CourtCase(val raw: JSONObject) {
    val number get() = raw.optString("رقم القضية", "—")
    fun field(key: String) = raw.optString(key).takeIf { it.isNotBlank() && it != "null" }
}
private data class CourtUser(val id: Int, val name: String, val phone: String)
private data class AuditEvent(val action: String, val name: String, val phone: String, val time: String)

@Composable
private fun CourtApp() {
    val scope = rememberCoroutineScope()
    var token by remember { mutableStateOf<String?>(null) }
    var role by remember { mutableStateOf("user") }
    var displayName by remember { mutableStateOf("") }
    var page by remember { mutableStateOf("auth") }
    var registration by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var query by remember { mutableStateOf("") }
    var sessionDate by remember { mutableStateOf("") }
    var cases by remember { mutableStateOf(emptyList<CourtCase>()) }
    var sessions by remember { mutableStateOf(emptyList<CourtCase>()) }
    var users by remember { mutableStateOf(emptyList<CourtUser>()) }
    var events by remember { mutableStateOf(emptyList<AuditEvent>()) }
    var message by remember { mutableStateOf("") }
    var busy by remember { mutableStateOf(false) }

    fun launchRequest(block: suspend () -> Unit) {
        if (busy) return
        busy = true
        message = ""
        scope.launch {
            try { withContext(Dispatchers.IO) { block() } }
            catch (e: Exception) { message = e.message ?: "تعذر الاتصال بالخادم." }
            finally { busy = false }
        }
    }

    Surface(Modifier.fillMaxSize(), color = Page) {
        when (page) {
            "auth" -> AuthPage(registration, name, phone, password, busy, message,
                { name = it }, { phone = it }, { password = it },
                { registration = !registration; message = "" }, {
                    launchRequest {
                        if (registration) {
                            val result = Api.register(name, phone, password)
                            message = result.optString("message", "تم إرسال طلبك إلى مدير النظام للمراجعة.")
                            registration = false
                            password = ""
                        } else {
                            val result = Api.login(phone, password)
                            token = result.getString("access_token")
                            val user = result.getJSONObject("user")
                            role = user.optString("role", "user")
                            displayName = user.optString("name", "")
                            password = ""
                            page = "home"
                        }
                    }
                })
            "home" -> HomePage(displayName, role, query, cases, busy, message, { query = it },
                { launchRequest { cases = Api.search(token!!, query).map(::CourtCase) } },
                { page = "sessions" }, { page = "admin" }, {
                    token = null; cases = emptyList(); page = "auth"; message = "تم تسجيل الخروج"
                })
            "sessions" -> SessionsPage(sessionDate, sessions, busy, message, { sessionDate = it }, { page = "home" }, {
                launchRequest { sessions = Api.sessions(token!!, sessionDate).map(::CourtCase) }
            })
            else -> AdminPage(users, events, busy, message, { page = "home" },
                { launchRequest { users = Api.pendingUsers(token!!) } },
                { launchRequest { events = Api.audit(token!!) } },
                { user, approve -> launchRequest { Api.decide(token!!, user.id, approve); users = Api.pendingUsers(token!!) } })
        }
    }
}

@Composable
private fun AuthPage(register: Boolean, name: String, phone: String, password: String, busy: Boolean, message: String,
                     onName: (String) -> Unit, onPhone: (String) -> Unit, onPassword: (String) -> Unit,
                     onToggle: () -> Unit, onSubmit: () -> Unit) {
    Column(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color.White, Page, Color(0xFFF0EEE8))).padding(horizontal = 24.dp), horizontalAlignment = Alignment.CenterHorizontally) {
        Spacer(Modifier.height(52.dp))
        Box(Modifier.size(112.dp).clip(CircleShape).background(Color(0xFFFFFCF5)), contentAlignment = Alignment.Center) {
            Text("⚖", fontSize = 58.sp, color = Gold)
        }
        Spacer(Modifier.height(14.dp))
        Text("محكمة البيضاء", fontSize = 29.sp, fontWeight = FontWeight.Bold, color = Navy)
        Text("نظام الاستعلام الإلكتروني", fontSize = 14.sp, color = Muted)
        Spacer(Modifier.height(26.dp))
        Text(if (register) "إنشاء حساب" else "مرحباً بك", fontSize = 23.sp, fontWeight = FontWeight.Bold, color = Navy)
        Text(if (register) "يُفعّل الحساب بعد موافقة مدير النظام" else "سجّل الدخول للمتابعة", color = Muted, fontSize = 13.sp, textAlign = TextAlign.Center)
        Spacer(Modifier.height(18.dp))
        Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = Color.White), elevation = CardDefaults.cardElevation(3.dp)) {
            Column(Modifier.padding(19.dp), verticalArrangement = Arrangement.spacedBy(11.dp)) {
                if (register) Field(name, onName, "الاسم الكامل")
                Field(phone, onPhone, "رقم الجوال", KeyboardType.Phone)
                OutlinedTextField(password, onPassword, Modifier.fillMaxWidth(), label = { Text("كلمة المرور") }, visualTransformation = PasswordVisualTransformation(), keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password), shape = RoundedCornerShape(14.dp), singleLine = true)
                Button(onClick = onSubmit, enabled = !busy && phone.isNotBlank() && password.isNotBlank() && (!register || name.isNotBlank()), modifier = Modifier.fillMaxWidth().height(51.dp), shape = RoundedCornerShape(14.dp), colors = ButtonDefaults.buttonColors(containerColor = Navy)) {
                    Text(if (busy) "جارٍ التنفيذ..." else if (register) "إرسال طلب التسجيل" else "تسجيل الدخول", fontWeight = FontWeight.Bold)
                }
                TextButton(onClick = onToggle, modifier = Modifier.fillMaxWidth()) { Text(if (register) "لديك حساب؟ تسجيل الدخول" else "مستخدم جديد؟ إنشاء حساب", color = Navy) }
            }
        }
        if (message.isNotBlank()) Text(message, Modifier.padding(top = 14.dp), color = Navy, textAlign = TextAlign.Center)
        Spacer(Modifier.weight(1f))
        Text("تقنية معلومات محكمة البيضاء الابتدائية", Modifier.padding(bottom = 20.dp), color = Muted, fontSize = 12.sp)
    }
}

@Composable
private fun HomePage(userName: String, role: String, query: String, cases: List<CourtCase>, busy: Boolean, message: String,
                     onQuery: (String) -> Unit, onSearch: () -> Unit, onSessions: () -> Unit,
                     onAdmin: () -> Unit, onLogout: () -> Unit) {
    Column(Modifier.fillMaxSize().padding(horizontal = 18.dp)) {
        Row(Modifier.fillMaxWidth().padding(top = 16.dp, bottom = 15.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
            Column {
                Text("مرحباً بك", color = Muted, fontSize = 13.sp)
                Text(userName, color = Navy, fontSize = 21.sp, fontWeight = FontWeight.Bold)
                if (role == "admin") Text("مدير النظام", color = Gold, fontWeight = FontWeight.Bold, fontSize = 12.sp)
            }
            Row(verticalAlignment = Alignment.CenterVertically) { Text("⚖", color = Gold, fontSize = 29.sp); TextButton(onClick = onLogout) { Text("خروج", color = Navy) } }
        }
        Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(22.dp), colors = CardDefaults.cardColors(containerColor = Navy)) {
            Row(Modifier.fillMaxWidth().background(Brush.horizontalGradient(listOf(NavyDark, Navy, Color(0xFF38596B)))).padding(19.dp), verticalAlignment = Alignment.CenterVertically) {
