private object Api {
    private val http = OkHttpClient.Builder().connectTimeout(15, TimeUnit.SECONDS).readTimeout(30, TimeUnit.SECONDS).build()
    private val jsonType = "application/json; charset=utf-8".toMediaType()
    private fun base(): String {
        val url = BuildConfig.API_BASE_URL.trim().trimEnd('/')
        check(url.startsWith("https://") && !url.contains("example.invalid")) { "عنوان الخادم غير مضبوط. يجب نشر API وضبط API_BASE_URL إلى رابط HTTPS." }
        return url
    }
    private fun call(path: String, body: JSONObject? = null, token: String? = null): String {
        val builder = Request.Builder().url(base() + path).header("Accept", "application/json")
        if (token != null) builder.header("Authorization", "Bearer $token")
        if (body != null) builder.post(body.toString().toRequestBody(jsonType)) else builder.get()
        http.newCall(builder.build()).execute().use { response ->
            val text = response.body?.string().orEmpty()
            if (!response.isSuccessful) {
                val detail = try { JSONObject(text).optString("detail") } catch (_: Exception) { "" }
                error(detail.ifBlank { "فشل الطلب (${response.code})." })
            }
            return text
        }
    }
    fun register(name: String, phone: String, password: String) = JSONObject(call("/api/auth/register", JSONObject().put("name", name).put("phone", phone).put("password", password)))
    fun login(phone: String, password: String) = JSONObject(call("/api/auth/login", JSONObject().put("phone", phone).put("password", password)))
    fun search(token: String, query: String): List<JSONObject> {
        val q = URLEncoder.encode(query, "UTF-8")
        val array = JSONObject(call("/api/cases/search?q=$q&limit=30", token = token)).getJSONArray("cases")
        return (0 until array.length()).map { array.getJSONObject(it) }
    }
    fun sessions(token: String, date: String): List<JSONObject> {
        val d = URLEncoder.encode(date, "UTF-8")
        val array = JSONObject(call("/api/sessions?date=$d", token = token)).getJSONArray("sessions")
        return (0 until array.length()).map { array.getJSONObject(it) }
    }
    fun pendingUsers(token: String): List<CourtUser> {
        val array = JSONObject(call("/api/admin/users?state=pending", token = token)).getJSONArray("users")
        return (0 until array.length()).map { val u = array.getJSONObject(it); CourtUser(u.getInt("id"), u.optString("name"), u.optString("phone")) }
    }
    fun decide(token: String, id: Int, approve: Boolean) { call("/api/admin/users/$id/decision", JSONObject().put("approve", approve), token) }
    fun audit(token: String): List<AuditEvent> {
        val array = JSONObject(call("/api/admin/activity?limit=150", token = token)).getJSONArray("events")
        return (0 until array.length()).map { i ->
            val row = array.getJSONObject(i); val actor = row.optJSONObject("actor")
            AuditEvent(row.optString("action"), actor?.optString("name").orEmpty(), actor?.optString("phone").orEmpty(), row.optString("created_at"))
        }
    }
}
