        Box(Modifier.size(112.dp).clip(CircleShape).background(Color(0xFFFFFCF5)), contentAlignment = Alignment.Center) { Text("⚖", fontSize = 58.sp, color = Gold) }
        Spacer(Modifier.height(14.dp))
        Text("محكمة البيضاء", fontSize = 29.sp, fontWeight = FontWeight.Bold, color = Navy)
