@Composable
private fun AdminPage(users: List<CourtUser>, events: List<AuditEvent>, busy: Boolean, message: String, onBack: () -> Unit,
                      onUsers: () -> Unit, onEvents: () -> Unit, onDecision: (CourtUser, Boolean) -> Unit) {
    Column(Modifier.fillMaxSize().padding(17.dp)) {
        PageHeader("إدارة النظام", onBack)
        Text("طلبات الحسابات وسجل النشاط خاصان بمدير النظام.", color = Muted, fontSize = 13.sp)
        Spacer(Modifier.height(10.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(onClick = onUsers, enabled = !busy, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = Navy)) { Text("طلبات التسجيل") }
            OutlinedButton(onClick = onEvents, enabled = !busy, modifier = Modifier.weight(1f)) { Text("سجل النشاط", color = Navy) }
        }
        if (message.isNotBlank()) Text(message, color = Navy, modifier = Modifier.padding(vertical = 7.dp))
        LazyColumn(Modifier.weight(1f), contentPadding = PaddingValues(vertical = 8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            items(users, key = { it.id }) { user ->
                Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(15.dp), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                    Column(Modifier.padding(13.dp)) {
                        Text(user.name, color = Navy, fontWeight = FontWeight.Bold); Text(user.phone, color = Muted, fontSize = 13.sp)
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            Button(onClick = { onDecision(user, true) }, enabled = !busy, colors = ButtonDefaults.buttonColors(containerColor = Gold)) { Text("موافقة", color = Navy) }
                            OutlinedButton(onClick = { onDecision(user, false) }, enabled = !busy) { Text("رفض") }
                        }
                    }
                }
            }
            items(events) { event ->
                Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(14.dp), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                    Column(Modifier.padding(12.dp)) {
                        Text(actionArabic(event.action), color = Navy, fontWeight = FontWeight.Bold)
                        Text(listOf(event.name, event.phone).filter { it.isNotBlank() }.joinToString(" • ").ifBlank { "نشاط نظام" }, color = Muted, fontSize = 12.sp)
                        if (event.details.isNotBlank()) Text(event.details, color = Muted, fontSize = 12.sp)
                        Text(event.time, color = Muted, fontSize = 11.sp)
                    }
                }
            }
        }
    }
}

private fun actionArabic(action: String): String = when (action) {
    "registration_submitted" -> "إرسال طلب تسجيل"
    "login_succeeded" -> "تسجيل دخول ناجح"
    "login_failed" -> "محاولة دخول غير ناجحة"
    "login_denied_unapproved" -> "محاولة دخول لحساب غير معتمد"
    "user_approved" -> "اعتماد حساب"
    "user_rejected" -> "رفض حساب"
    "case_types_viewed" -> "عرض أنواع القضايا"
    "case_search" -> "البحث في القضايا"
    "sessions_search" -> "البحث عن الجلسات"
    "case_pdf_downloaded" -> "تنزيل ملف القضية PDF"
    "admin_users_listed" -> "مراجعة حسابات المستخدمين"
    "admin_activity_viewed" -> "عرض سجل النشاط الإداري"
    else -> action
}

