class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.statusBarColor = android.graphics.Color.rgb(246, 246, 244)
        window.navigationBarColor = android.graphics.Color.rgb(246, 246, 244)
        window.decorView.systemUiVisibility = android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR or android.view.View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR
        setContent { CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) { CourtTheme { CourtApp() } } }
    }
}

@Composable private fun CourtTheme(content: @Composable () -> Unit) {
    MaterialTheme(colorScheme = lightColorScheme(primary = Navy, secondary = Gold, background = Page, surface = Color.White, onPrimary = Color.White, onSurface = Navy), content = content)
}
private data class CourtCase(val raw: JSONObject) {
    val number get() = raw.optString("رقم القضية", "—")
    fun field(key: String) = raw.optString(key).takeIf { it.isNotBlank() && it != "null" }
}
private data class PendingUser(val id: Int, val name: String, val phone: String)
private data class AuditEvent(val action: String, val actor: String, val whenAt: String, val details: String)

@Composable private fun CourtApp() {
    val scope = rememberCoroutineScope()
    var token by remember { mutableStateOf<String?>(null) }
    var role by remember { mutableStateOf("") }
    var userName by remember { mutableStateOf("") }
    var page by remember { mutableStateOf("login") }
    var registering by remember { mutableStateOf(false) }
    var fullName by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var query by remember { mutableStateOf("") }
    var date by remember { mutableStateOf("") }
    var cases by remember { mutableStateOf(emptyList<CourtCase>()) }
    var sessions by remember { mutableStateOf(emptyList<CourtCase>()) }
    var pending by remember { mutableStateOf(emptyList<PendingUser>()) }
    var audit by remember { mutableStateOf(emptyList<AuditEvent>()) }
    var busy by remember { mutableStateOf(false) }
    var notice by remember { mutableStateOf("") }

    fun runRequest(task: suspend () -> Unit) {
        if (busy) return
        busy = true
        notice = ""
        scope.launch {
            try { withContext(Dispatchers.IO) { task() } }
            catch (e: Exception) { notice = e.message ?: "تعذر إكمال الطلب." }
            finally { busy = false }
        }
    }

    when (page) {
        "login" -> LoginPage(registering, fullName, phone, password, busy, notice,
            { fullName = it }, { phone = it }, { password = it }, { registering = !registering; notice = "" }, {
                runRequest {
                    if (registering) {
                        val result = Api.register(fullName, phone, password)
                        notice = result.optString("message", "تم إرسال طلبك إلى مدير النظام للمراجعة.")
                        registering = false; password = ""
                    } else {
                        val result = Api.login(phone, password)
                        token = result.getString("access_token")
                        val user = result.getJSONObject("user")
                        role = user.optString("role", "user"); userName = user.optString("name")
                        password = ""; page = "home"
                    }
                }
            })
        "home" -> HomePage(userName, role, query, cases, busy, notice, { query = it },
            { runRequest { cases = Api.search(token!!, query).map(::CourtCase) } },
            { page = "sessions" }, { page = "admin" }, {
                token = null; role = ""; cases = emptyList(); page = "login"; notice = "تم تسجيل الخروج"
            })
        "sessions" -> SessionsPage(date, sessions, busy, notice, { date = it }, { page = "home" }, {
            runRequest { sessions = Api.sessions(token!!, date).map(::CourtCase) }
        })
        "admin" -> if (role == "admin") AdminPage(pending, audit, busy, notice, { page = "home" },
            { runRequest { pending = Api.pending(token!!) } },
            { runRequest { audit = Api.activity(token!!) } },
            { item, approve -> runRequest { Api.decide(token!!, item.id, approve); pending = Api.pending(token!!) } })
            else { page = "home"; notice = "هذه الصفحة لمدير النظام فقط." }
    }
}

@Composable private fun LoginPage(register: Boolean, name: String, phone: String, password: String, busy: Boolean, notice: String,
                                  onName: (String) -> Unit, onPhone: (String) -> Unit, onPassword: (String) -> Unit,
                                  onToggle: () -> Unit, onSubmit: () -> Unit) {
    Column(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color.White, Page, Color(0xFFF0EEE8)))).padding(horizontal = 24.dp), horizontalAlignment = Alignment.CenterHorizontally) {
        Spacer(Modifier.height(52.dp))
        Box(Modifier.size(108.dp).clip(CircleShape).background(Color(0xFFFFFCF5)), contentAlignment = Alignment.Center) { Text("⚖", fontSize = 58.sp, color = Gold) }
        Spacer(Modifier.height(14.dp)); Text("محكمة البيضاء", fontSize = 29.sp, fontWeight = FontWeight.Bold, color = Navy)
        Text("نظام الاستعلام الإلكتروني", fontSize = 14.sp, color = Muted)
        Spacer(Modifier.height(24.dp)); Text(if (register) "إنشاء حساب" else "مرحباً بك", fontSize = 23.sp, fontWeight = FontWeight.Bold, color = Navy)
        Text(if (register) "يُفعّل الحساب بعد موافقة مدير النظام" else "سجّل الدخول للمتابعة", color = Muted, fontSize = 13.sp)
        Spacer(Modifier.height(18.dp))
        Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = Color.White), elevation = CardDefaults.cardElevation(3.dp)) {
            Column(Modifier.padding(19.dp), verticalArrangement = Arrangement.spacedBy(11.dp)) {
                if (register) TextInput(name, onName, "الاسم الكامل")
                TextInput(phone, onPhone, "رقم الجوال", KeyboardType.Phone)
                OutlinedTextField(password, onPassword, Modifier.fillMaxWidth(), label = { Text("كلمة المرور") }, visualTransformation = PasswordVisualTransformation(), keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password), shape = RoundedCornerShape(14.dp), singleLine = true)
                Button(onClick = onSubmit, enabled = !busy && phone.isNotBlank() && password.isNotBlank() && (!register || name.isNotBlank()), modifier = Modifier.fillMaxWidth().height(51.dp), shape = RoundedCornerShape(14.dp), colors = ButtonDefaults.buttonColors(containerColor = Navy)) { Text(if (busy) "جارٍ التنفيذ..." else if (register) "إرسال طلب التسجيل" else "تسجيل الدخول", fontWeight = FontWeight.Bold) }
                TextButton(onClick = onToggle, modifier = Modifier.fillMaxWidth()) { Text(if (register) "لديك حساب؟ تسجيل الدخول" else "مستخدم جديد؟ إنشاء حساب", color = Navy) }
            }
        }
        if (notice.isNotBlank()) Text(notice, Modifier.padding(top = 14.dp), color = Navy, textAlign = TextAlign.Center)
        Spacer(Modifier.weight(1f)); Text("تقنية معلومات محكمة البيضاء الابتدائية", Modifier.padding(bottom = 20.dp), color = Muted, fontSize = 12.sp)
    }
}

@Composable private fun HomePage(name: String, role: String, query: String, cases: List<CourtCase>, busy: Boolean, notice: String,
                                 onQuery: (String) -> Unit, onSearch: () -> Unit, onSessions: () -> Unit,
                                 onAdmin: () -> Unit, onLogout: () -> Unit) {
    Column(Modifier.fillMaxSize().padding(horizontal = 18.dp)) {
        Row(Modifier.fillMaxWidth().padding(top = 15.dp, bottom = 14.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
            Column { Text("مرحباً بك", color = Muted, fontSize = 13.sp); Text(name, color = Navy, fontSize = 21.sp, fontWeight = FontWeight.Bold); if (role == "admin") Text("مدير النظام", color = Gold, fontWeight = FontWeight.Bold, fontSize = 12.sp) }
            Row(verticalAlignment = Alignment.CenterVertically) { Text("⚖", color = Gold, fontSize = 28.sp); TextButton(onClick = onLogout) { Text("خروج", color = Navy) } }
        }
        Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(22.dp), colors = CardDefaults.cardColors(containerColor = Navy)) {
            Row(Modifier.fillMaxWidth().background(Brush.horizontalGradient(listOf(Color(0xFF173247), Navy, Color(0xFF38596B)))).padding(19.dp), verticalAlignment = Alignment.CenterVertically) {
                Column(Modifier.weight(1f)) { Text("محكمة البيضاء الابتدائية", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 18.sp); Spacer(Modifier.height(5.dp)); Text("خدمات الاستعلام القضائي", color = Color(0xFFE7D8B3), fontSize = 13.sp) }
                Text("⚖", color = Gold, fontSize = 42.sp)
            }
        }
        Spacer(Modifier.height(20.dp)); Text("الخدمات القانونية", Modifier.fillMaxWidth(), fontSize = 19.sp, color = Navy, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(10.dp)); Row(horizontalArrangement = Arrangement.spacedBy(9.dp)) {
            ServiceTile("🔎", "البحث عن قضية", Modifier.weight(1f)) {}
            ServiceTile("📅", "الجلسات اليومية", Modifier.weight(1f), onSessions)
            if (role == "admin") ServiceTile("🛡", "إدارة النظام", Modifier.weight(1f), onAdmin)
        }
        Spacer(Modifier.height(19.dp)); Text("البحث في سجل القضايا", Modifier.fillMaxWidth(), fontSize = 18.sp, color = Navy, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(9.dp))
        Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(20.dp), colors = CardDefaults.cardColors(containerColor = Color.White), elevation = CardDefaults.cardElevation(2.dp)) {
            Column(Modifier.padding(15.dp)) { TextInput(query, onQuery, "رقم القضية أو اسم أحد الأطراف"); Spacer(Modifier.height(9.dp)); Button(onClick = onSearch, enabled = !busy && query.isNotBlank(), modifier = Modifier.fillMaxWidth().height(47.dp), shape = RoundedCornerShape(14.dp), colors = ButtonDefaults.buttonColors(containerColor = Navy)) { Text(if (busy) "جارٍ البحث..." else "بحث", fontWeight = FontWeight.Bold) } }
        }
        if (notice.isNotBlank()) Text(notice, Modifier.padding(vertical = 7.dp), color = Navy, fontSize = 13.sp)
        LazyColumn(Modifier.weight(1f), contentPadding = PaddingValues(vertical = 10.dp), verticalArrangement = Arrangement.spacedBy(9.dp)) { items(cases, key = { it.number }) { CaseCard(it) } }
    }
}

@Composable private fun ServiceTile(icon: String, title: String, modifier: Modifier = Modifier, onClick: () -> Unit) {
    Card(onClick = onClick, modifier = modifier.height(103.dp), shape = RoundedCornerShape(18.dp), colors = CardDefaults.cardColors(containerColor = Color.White), elevation = CardDefaults.cardElevation(2.dp)) {
        Column(Modifier.fillMaxSize().padding(8.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.Center) { Box(Modifier.size(39.dp).clip(CircleShape).background(Color(0xFFFAF6EC)), contentAlignment = Alignment.Center) { Text(icon, fontSize = 20.sp) }; Spacer(Modifier.height(6.dp)); Text(title, color = Navy, fontSize = 11.sp, textAlign = TextAlign.Center, fontWeight = FontWeight.SemiBold) }
    }
}
@Composable private fun CaseCard(item: CourtCase) {
    Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(18.dp), colors = CardDefaults.cardColors(containerColor = Color.White), elevation = CardDefaults.cardElevation(1.dp)) {
        Column(Modifier.padding(14.dp)) {
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { Text("القضية ${item.number}", color = Navy, fontWeight = FontWeight.Bold, fontSize = 16.sp); Text("⚖", color = Gold) }
            listOf("نوع القضية" to item.field("نوع القضية"), "المدعي" to item.field("المدعي"), "المدعى عليه" to item.field("المدعى عليه"), "القاضي" to item.field("برئاسة القاضي"), "الجلسة القادمة" to item.field("الجلسة القادمة"), "الموضوع" to item.field("موضوعها")).forEach { (label, value) -> if (value != null) Text("$label: $value", color = Muted, fontSize = 13.sp, modifier = Modifier.padding(top = 4.dp)) }
        }
    }
}

@Composable private fun SessionsPage(date: String, sessions: List<CourtCase>, busy: Boolean, notice: String, onDate: (String) -> Unit, onBack: () -> Unit, onSearch: () -> Unit) {
    Column(Modifier.fillMaxSize().padding(18.dp)) {
        PageHeader("الجلسات اليومية", onBack); Text("أدخل التاريخ بصيغة YYYY-MM-DD", color = Muted, fontSize = 13.sp)
        Spacer(Modifier.height(10.dp)); TextInput(date, onDate, "تاريخ الجلسة"); Spacer(Modifier.height(9.dp))
