private fun actionArabic(a: String) = when (a) {
    "registration_submitted" -> "إرسال طلب تسجيل"; "login_succeeded" -> "تسجيل دخول ناجح"; "login_failed" -> "محاولة دخول غير ناجحة"; "login_denied_unapproved" -> "محاولة دخول لحساب غير معتمد"; "user_approved" -> "اعتماد حساب"; "user_rejected" -> "رفض حساب"; "case_types_viewed" -> "عرض أنواع القضايا"; "case_search" -> "البحث في القضايا"; "sessions_search" -> "البحث عن الجلسات"; "case_pdf_downloaded" -> "تنزيل ملف القضية"; "admin_users_listed" -> "مراجعة حسابات المستخدمين"; "admin_activity_viewed" -> "عرض سجل النشاط الإداري"; else -> a
}
@Composable private fun PageHeader(title: String, onBack: () -> Unit) { Row(Modifier.fillMaxWidth().padding(bottom = 12.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) { Text(title, color = Navy, fontWeight = FontWeight.Bold, fontSize = 22.sp); TextButton(onClick = onBack) { Text("عودة", color = Gold) } } }
@Composable private fun TextInput(value: String, onValue: (String) -> Unit, label: String, keyboard: KeyboardType = KeyboardType.Text) { OutlinedTextField(value, onValue, modifier = Modifier.fillMaxWidth(), label = { Text(label) }, keyboardOptions = KeyboardOptions(keyboardType = keyboard), shape = RoundedCornerShape(14.dp), singleLine = true) }

private object Api {
    private val http = OkHttpClient.Builder().connectTimeout(15, TimeUnit.SECONDS).readTimeout(30, TimeUnit.SECONDS).build()
    private val jsonType = "application/json; charset=utf-8".toMediaType()
    private fun base(): String { val url = BuildConfig.API_BASE_URL.trim().trimEnd('/'); check(url.startsWith("https://") && !url.contains("example.invalid")) { "اضبط عنوان API_BASE_URL الحقيقي باستخدام HTTPS." }; return url }
    private fun call(path: String, body: JSONObject? = null, token: String? = null): String {
        val builder = Request.Builder().url(base() + path).header("Accept", "application/json")
        if (token != null) builder.header("Authorization", "Bearer $token")
        if (body != null) builder.post(body.toString().toRequestBody(jsonType)) else builder.get()
        http.newCall(builder.build()).execute().use { response ->
            val text = response.body?.string().orEmpty()
            if (!response.isSuccessful) { val detail = try { JSONObject(text).optString("detail") } catch (_: Exception) { "" }; error(detail.ifBlank { "فشل الطلب (${response.code})." }) }
            return text
        }
    }
    fun register(n: String,p: String,w: String) = JSONObject(call("/api/auth/register", JSONObject().put("name",n).put("phone",p).put("password",w)))
    fun login(p: String,w: String) = JSONObject(call("/api/auth/login", JSONObject().put("phone",p).put("password",w)))
    fun search(t:String,q:String):List<JSONObject> { val a=JSONObject(call("/api/cases/search?q=${URLEncoder.encode(q,"UTF-8")}&limit=30",token=t)).getJSONArray("cases"); return (0 until a.length()).map { a.getJSONObject(it) } }
    fun sessions(t:String,d:String):List<JSONObject> { val a=JSONObject(call("/api/sessions?date=${URLEncoder.encode(d,"UTF-8")}",token=t)).getJSONArray("sessions"); return (0 until a.length()).map { a.getJSONObject(it) } }
    fun pending(t:String):List<PendingUser> { val a=JSONObject(call("/api/admin/users?state=pending",token=t)).getJSONArray("users"); return (0 until a.length()).map { val u=a.getJSONObject(it); PendingUser(u.getInt("id"),u.optString("name"),u.optString("phone")) } }
    fun decide(t:String,id:Int,approve:Boolean) { call("/api/admin/users/$id/decision",JSONObject().put("approve",approve),t) }
    fun activity(t:String):List<AuditEvent> { val a=JSONObject(call("/api/admin/activity?limit=150",token=t)).getJSONArray("events"); return (0 until a.length()).map { i -> val e=a.getJSONObject(i); val actor=e.optJSONObject("actor"); val m=e.optJSONObject("metadata"); val details=if (m?.has("result_count")==true) "عدد النتائج: ${m.optInt("result_count")}" else ""; AuditEvent(e.optString("action"),listOfNotNull(actor?.optString("name"),actor?.optString("phone")).filter { it.isNotBlank() }.joinToString(" • "),e.optString("created_at"),details) } }
}
