{"branch":"main","content":""""Additional admin tools and advanced case search routes.

Imported by api.py after its auth/database helpers are defined. The dependencies
are applied server-side; UI visibility is not an authorization boundary.
"""
from __future__ import annotations

import json
from datetime import datetime
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query
from pydantic import BaseModel, Field

from api import _admin, _audit, _db, _now, _phone, _public, _current, HASHER
from case_records import CaseRecordsError, load_case_records, search_case_records

router = APIRouter()


class UserPatch(BaseModel):
    name: str | None = Field(default=None, min_length=2, max_length=120)
    phone: str | None = Field(default=None, min_length=7, max_length=24)
    state: str | None = Field(default=None, pattern="^(pending|approved|rejected)$")
    password: str | None = Field(default=None, min_length=10, max_length=128)


@router.get("/api/admin/users/manage")
def manage_users(
