    if session_from:
        results = [r for r in results if (iso(r.get("الجلسة القادمة")) or "") >= session_from]
    if session_to:
        results = [r for r in results if (iso(r.get("الجلسة القادمة")) or "") <= session_to]
    results = results[:limit]
    _audit(user["id"], "advanced_case_search", metadata={"result_count": len(results), "has_date_filter": bool(session_from or session_to)})
