                }
            }
        )

        "admin" -> AdminPage(
            users = pending,
            events = audit,
            stats = stats,
            busy = busy,
            notice = notice,
            onBack = { currentPage = "home" },
            onLoadUsers = {
                request {
                    pending = Api.pendingUsers(token!!)
                }
            },
            onLoadStats = {
                request {
                    stats = Api.stats(token!!)
                }
            },
            onLoadActivity = {
                request {
                    audit = Api.audit(token!!)
                }
            },
            onDecision = { user, approve ->
                request {
                    Api.decide(token!!, user.id, approve)
                    pending = Api.pendingUsers(token!!)
                }
            }
        )
    }
