    }
    private fun savePdf(name:String, bytes:ByteArray) {
        val file=File(cacheDir,"case_${name.replace(Regex("[^A-Za-z0-9_-]"),"_")}.pdf"); file.writeBytes(bytes)
        val uri:Uri=FileProvider.getUriForFile(this,"$packageName.fileprovider",file)
        startActivity(Intent.createChooser(Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"فتح ملف القضية"))
    }
}

@Composable private fun CourtApp(savePdf:(String,ByteArray)->Unit) {
    val scope= rememberCoroutineScope(); var token by remember { mutableStateOf<String?>(null) }; var role by remember { mutableStateOf("") }; var myName by remember { mutableStateOf("") }
    var page by remember { mutableStateOf("auth") }; var registering by remember { mutableStateOf(false) }; var name by remember { mutableStateOf("") }; var phone by remember { mutableStateOf("") }; var password by remember { mutableStateOf("") }
    var q by remember { mutableStateOf("") }; var type by remember { mutableStateOf("all") }; var judge by remember { mutableStateOf("all") }; var from by remember { mutableStateOf("") }; var to by remember { mutableStateOf("") }; var pdfNumber by remember { mutableStateOf("") }; var date by remember { mutableStateOf("") }
    var cases by remember { mutableStateOf(emptyList<CaseRow>()) }; var sessions by remember { mutableStateOf(emptyList<CaseRow>()) }; var users by remember { mutableStateOf(emptyList<UserRow>()) }; var events by remember { mutableStateOf(emptyList<EventRow>()) }; var stats by remember { mutableStateOf<JSONObject?>(null) }
    var busy by remember { mutableStateOf(false) }; var message by remember { mutableStateOf("") }
    fun request(work:suspend()->Unit) { if(busy)return; busy=true; message=""; scope.launch { try { withContext(Dispatchers.IO){work()} } catch(e:Exception){message=e.message ?: "تعذر الاتصال بالخادم"} finally { busy=false } } }
    Surface(Modifier.fillMaxSize(),color=Color.Transparent) {
