                Spacer(Modifier.height(20.dp)); Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(20.dp)) { Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)) {
                    if(registering) Field(name,{name=it},"الاسم الكامل")
                    Field(phone,{phone=it},"رقم الجوال",KeyboardType.Phone); OutlinedTextField(password,{password=it},label={Text("كلمة المرور")},modifier=Modifier.fillMaxWidth(),visualTransformation=PasswordVisualTransformation(),singleLine=true)
                    Button(enabled=!busy,onClick={request { if(registering){val r=Api.register(name,phone,password); message=r.optString("message"); registering=false} else {val r=Api.login(phone,password); token=r.getString("access_token"); val u=r.getJSONObject("user"); role=u.optString("role"); myName=u.optString("name"); page="home"} }},modifier=Modifier.fillMaxWidth()){Text(if(busy)"جارٍ التنفيذ" else if(registering)"إرسال طلب" else "دخول")}
                    TextButton(onClick={registering=!registering}){Text(if(registering)"لدي حساب" else "إنشاء حساب")}
                } }; Notice(message)
