                Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Field(from,{from=it},"من تاريخ YYYY-MM-DD",modifier=Modifier.weight(1f));Field(to,{to=it},"إلى تاريخ",modifier=Modifier.weight(1f))}
                Button(enabled=!busy,onClick={request{cases=Api.advanced(token!!,q,type,judge,from,to).map(::CaseRow)}},modifier=Modifier.fillMaxWidth()){Text("بحث")}
                Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Field(pdfNumber,{pdfNumber=it},"رقم القضية لـ PDF",modifier=Modifier.weight(1f));Button(enabled=!busy,onClick={request{savePdf(pdfNumber,Api.pdf(token!!,pdfNumber))}}){Text("PDF")}}
                Button(onClick={page="sessions"},modifier=Modifier.fillMaxWidth()){Text("الجلسات")}
