@Composable private fun Field(value:String,onChange:(String)->Unit,label:String,type:KeyboardType=KeyboardType.Text,modifier:Modifier=Modifier.fillMaxWidth()){OutlinedTextField(value,onChange,modifier=modifier,label={Text(label)},singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=type))}
@Composable private fun Notice(value:String){if(value.isNotBlank())Text(value,Modifier.fillMaxWidth().padding(8.dp),color=Navy,textAlign=TextAlign.Center)}
@Composable private fun Header(title:String,back:()->Unit){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text(title,fontSize=20.sp,fontWeight=FontWeight.Bold,color=Navy);TextButton(onClick=back){Text("عودة")}}}
@Composable private fun CaseCard(row:CaseRow){Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("القضية ${row.number}",fontWeight=FontWeight.Bold,color=Navy);listOf("نوع القضية","المدعي","المدعى عليه","برئاسة القاضي","الجلسة القادمة","موضوعها").forEach{key->val v=row.json.optString(key);if(v.isNotBlank()&&v!="null")Text("$key: $v",color=Muted)}}}}

private object Api {
    private val client=OkHttpClient.Builder().connectTimeout(15,TimeUnit.SECONDS).readTimeout(45,TimeUnit.SECONDS).build()
    private val json="application/json; charset=utf-8".toMediaType()
    private fun url(path:String)=BuildConfig.API_BASE_URL.trimEnd('/')+path
    private fun request(path:String,token:String?=null,body:JSONObject?=null,method:String="GET"):String { val b=Request.Builder().url(url(path)).header("Accept","application/json");if(token!=null)b.header("Authorization","Bearer $token");if(body!=null)b.method(method,body.toString().toRequestBody(json)) else b.method(method,null);client.newCall(b.build()).execute().use{r->val text=r.body?.string().orEmpty();if(!r.isSuccessful)error(try{JSONObject(text).optString("detail").ifBlank{"HTTP ${r.code}"}catch(_:Exception){"HTTP ${r.code}"});return text} }
    fun register(n:String,p:String,w:String)=JSONObject(request("/api/auth/register",body=JSONObject().put("name",n).put("phone",p).put("password",w),method="POST"))
    fun login(p:String,w:String)=JSONObject(request("/api/auth/login",body=JSONObject().put("phone",p).put("password",w),method="POST"))
    private fun array(path:String,t:String,key:String)=JSONObject(request(path,t)).getJSONArray(key).let{a->(0 until a.length()).map{a.getJSONObject(it)}}
    fun advanced(t:String,q:String,type:String,judge:String,from:String,to:String):List<JSONObject>{val p=mutableListOf<String>();if(q.isNotBlank())p+="q="+enc(q);p+="case_type="+enc(type);p+="judge="+enc(judge);if(from.isNotBlank())p+="session_from="+enc(from);if(to.isNotBlank())p+="session_to="+enc(to);p+="limit=50";return array("/api/cases/advanced-search?"+p.joinToString("&"),t,"cases")}
    fun sessions(t:String,d:String)=array("/api/sessions?date="+enc(d),t,"sessions")
    fun users(t:String,state:String):List<UserRow> = array("/api/admin/users/manage?state=$state&limit=200",t,"users").map{UserRow(it.optInt("id"),it.optString("name"),it.optString("phone"),it.optString("state"),it.optString("role"))}
    fun patchUser(t:String,id:Int,body:JSONObject){request("/api/admin/users/$id",t,body,"PATCH")}
    fun stats(t:String)=JSONObject(request("/api/admin/reports/stats",t))
    fun activity(t:String)=array("/api/admin/activity?limit=200",t,"events").map{val actor=it.optJSONObject("actor");EventRow(it.optString("action"),actor?.optString("name").orEmpty(),it.optString("created_at"),it.optJSONObject("metadata")?.toString().orEmpty())}
    fun pdf(t:String,number:String):ByteArray { val b=Request.Builder().url(url("/api/cases/pdf")).header("Authorization","Bearer $t").post(JSONObject().put("case_number",number).toString().toRequestBody(json));client.newCall(b.build()).execute().use{r->if(!r.isSuccessful)error("تعذر تنزيل PDF (${r.code})");return r.body?.bytes()?:error("ملف PDF فارغ") } }
    private fun enc(s:String)=URLEncoder.encode(s,"UTF-8")
}
