private data class CaseRow(val json: JSONObject) { val number get() = json.optString("رقم القضية", "—") }
private data class UserRow(val id:Int,val name:String,val phone:String,val state:String,val role:String)
private data class EventRow(val action:String,val actor:String,val date:String,val meta:String)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.statusBarColor = android.graphics.Color.rgb(255,255,255)
        window.navigationBarColor = android.graphics.Color.rgb(255,255,255)
        window.decorView.systemUiVisibility = android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR or android.view.View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR
        setContent { CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) { MaterialTheme(colorScheme=lightColorScheme(primary=Navy,secondary=Gold,background=Color.Transparent,surface=Color.White)) { CourtApp(::savePdf) } } }
    }
    private fun savePdf(name:String, bytes:ByteArray) {
        val file=File(cacheDir,"case_${name.replace(Regex("[^A-Za-z0-9_-]"),"_")}.pdf"); file.writeBytes(bytes)
        val uri:Uri=FileProvider.getUriForFile(this,"$packageName.fileprovider",file)
        startActivity(Intent.createChooser(Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"فتح ملف القضية"))
    }
}

@Composable private fun CourtApp(savePdf:(String,ByteArray)->Unit) {
    val scope= rememberCoroutineScope(); var token by remember { mutableStateOf<String?>(null) }; var role by remember { mutableStateOf("") }; var myName by remember { mutableStateOf("") }
    var page by remember { mutableStateOf("auth") }; var registering by remember { mutableStateOf(false) }; var name by remember { mutableStateOf("") }; var phone by remember { mutableStateOf("") }; var password by remember { mutableStateOf("") }
    var q by remember { mutableStateOf("") }; var type by remember { mutableStateOf("all") }; var judge by remember { mutableStateOf("all") }; var from by remember { mutableStateOf("") }; var to by remember { mutableStateOf("") }; var pdfNumber by remember { mutableStateOf("") }; var date by remember { mutableStateOf("") }
    var cases by remember { mutableStateOf(emptyList<CaseRow>()) }; var sessions by remember { mutableStateOf(emptyList<CaseRow>()) }; var users by remember { mutableStateOf(emptyList<UserRow>()) }; var events by remember { mutableStateOf(emptyList<EventRow>()) }; var stats by remember { mutableStateOf<JSONObject?>(null) }
    var busy by remember { mutableStateOf(false) }; var message by remember { mutableStateOf("") }
    fun request(work:suspend()->Unit) { if(busy)return; busy=true; message=""; scope.launch { try { withContext(Dispatchers.IO){work()} } catch(e:Exception){message=e.message ?: "تعذر الاتصال بالخادم"} finally { busy=false } } }
    Surface(Modifier.fillMaxSize(),color=Color.Transparent) {
        when(page) {
            "auth" -> Column(Modifier.fillMaxSize().padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center) {
                Text("⚖",fontSize=60.sp,color=Gold); Text("محكمة البيضاء",fontSize=28.sp,fontWeight=FontWeight.Bold,color=Navy); Text(if(registering) "إنشاء حساب بانتظار الموافقة" else "نظام الاستعلام الإلكتروني",color=Muted)
                Spacer(Modifier.height(20.dp)); Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(20.dp)) { Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)) {
                    if(registering) Field(name,{name=it},"الاسم الكامل")
                    Field(phone,{phone=it},"رقم الجوال",KeyboardType.Phone); OutlinedTextField(password,{password=it},label={Text("كلمة المرور")},modifier=Modifier.fillMaxWidth(),visualTransformation=PasswordVisualTransformation(),singleLine=true)
                    Button(enabled=!busy,onClick={request { if(registering){val r=Api.register(name,phone,password); message=r.optString("message"); registering=false} else {val r=Api.login(phone,password); token=r.getString("access_token"); val u=r.getJSONObject("user"); role=u.optString("role"); myName=u.optString("name"); page="home"} }},modifier=Modifier.fillMaxWidth()){Text(if(busy)"جارٍ التنفيذ" else if(registering)"إرسال طلب" else "دخول")}
                    TextButton(onClick={registering=!registering}){Text(if(registering)"لدي حساب" else "إنشاء حساب")}
                } }; Notice(message)
            }
            "home" -> Column(Modifier.fillMaxSize().padding(16.dp)) {
                Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("مرحباً $myName",fontWeight=FontWeight.Bold,color=Navy);if(role=="admin")Text("مدير النظام",color=Gold)};TextButton(onClick={token=null;page="auth"}){Text("خروج")}}
                Text("بحث متقدم في القضايا",fontSize=20.sp,fontWeight=FontWeight.Bold,color=Navy)
                Field(q,{q=it},"رقم القضية أو اسم أحد الأطراف"); Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Field(type,{type=it},"نوع القضية (أو all)",modifier=Modifier.weight(1f));Field(judge,{judge=it},"القاضي (أو all)",modifier=Modifier.weight(1f))}
                Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Field(from,{from=it},"من تاريخ YYYY-MM-DD",modifier=Modifier.weight(1f));Field(to,{to=it},"إلى تاريخ",modifier=Modifier.weight(1f))}
                Button(enabled=!busy,onClick={request{cases=Api.advanced(token!!,q,type,judge,from,to).map(::CaseRow)}},modifier=Modifier.fillMaxWidth()){Text("بحث")}
                Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Field(pdfNumber,{pdfNumber=it},"رقم القضية لـ PDF",modifier=Modifier.weight(1f));Button(enabled=!busy,onClick={request{savePdf(pdfNumber,Api.pdf(token!!,pdfNumber))}}){Text("PDF")}}
                Button(onClick={page="sessions"},modifier=Modifier.fillMaxWidth()){Text("الجلسات")}
                if(role=="admin")Button(onClick={page="admin"},modifier=Modifier.fillMaxWidth()){Text("إدارة النظام والتقارير")}
                Notice(message)
                LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(cases,key={it.number}){CaseCard(it)}}
            }
            "sessions" -> Column(Modifier.fillMaxSize().padding(16.dp)){Header("الجلسات اليومية"){page="home"};Field(date,{date=it},"التاريخ YYYY-MM-DD");Button(enabled=!busy,onClick={request{sessions=Api.sessions(token!!,date).map(::CaseRow)}}){Text("بحث")};Notice(message);LazyColumn{items(sessions,key={it.number}){CaseCard(it)}}}
            "admin" -> if(role=="admin") Column(Modifier.fillMaxSize().padding(16.dp)) {
                Header("إدارة المستخدمين والتقارير"){page="home"}
                Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){Button(onClick={request{users=Api.users(token!!,"all")}},modifier=Modifier.weight(1f)){Text("كل المستخدمين")};Button(onClick={request{users=Api.users(token!!,"pending")}},modifier=Modifier.weight(1f)){Text("طلبات معلقة")}}
                Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){Button(onClick={request{stats=Api.stats(token!!)}},modifier=Modifier.weight(1f)){Text("إحصاءات")};Button(onClick={request{events=Api.activity(token!!)}},modifier=Modifier.weight(1f)){Text("سجل النشاط")}}
                stats?.let { Card(Modifier.fillMaxWidth()){Text(it.toString(2),Modifier.padding(12.dp),color=Navy)} }
                Notice(message)
                LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){
                    items(users,key={it.id}){u->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("${u.name} • ${u.phone}",fontWeight=FontWeight.Bold,color=Navy);Text("${u.role} / ${u.state}",color=Muted);Row{Button(onClick={request{Api.patchUser(token!!,u.id,JSONObject().put("state","approved"));users=Api.users(token!!,"all")}}){Text("اعتماد")};OutlinedButton(onClick={request{Api.patchUser(token!!,u.id,JSONObject().put("state","rejected"));users=Api.users(token!!,"all")}}){Text("إيقاف")}}}}
                    }
                    items(events){e->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){Text(e.action,fontWeight=FontWeight.Bold,color=Navy);Text(e.actor,color=Muted);Text(e.date,color=Muted);if(e.meta.isNotEmpty())Text(e.meta,color=Muted)}}}
                }
            } else { page="home" }
        }
    }
}

@Composable private fun Field(value:String,onChange:(String)->Unit,label:String,type:KeyboardType=KeyboardType.Text,modifier:Modifier=Modifier.fillMaxWidth()){OutlinedTextField(value,onChange,modifier=modifier,label={Text(label)},singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=type))}
@Composable private fun Notice(value:String){if(value.isNotBlank())Text(value,Modifier.fillMaxWidth().padding(8.dp),color=Navy,textAlign=TextAlign.Center)}
@Composable private fun Header(title:String,back:()->Unit){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text(title,fontSize=20.sp,fontWeight=FontWeight.Bold,color=Navy);TextButton(onClick=back){Text("عودة")}}}
@Composable private fun CaseCard(row:CaseRow){Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("القضية ${row.number}",fontWeight=FontWeight.Bold,color=Navy);listOf("نوع القضية","المدعي","المدعى عليه","برئاسة القاضي","الجلسة القادمة","موضوعها").forEach{key->val v=row.json.optString(key);if(v.isNotBlank()&&v!="null")Text("$key: $v",color=Muted)}}}}

private object Api {
    private val client=OkHttpClient.Builder().connectTimeout(15,TimeUnit.SECONDS).readTimeout(45,TimeUnit.SECONDS).build()
    private val json="application/json; charset=utf-8".toMediaType()
    private fun url(path:String)=BuildConfig.API_BASE_URL.trimEnd('/')+path
    private fun request(path:String,token:String?=null,body:JSONObject?=null,method:String="GET"):String { val b=Request.Builder().url(url(path)).header("Accept","application/json");if(token!=null)b.header("Authorization","Bearer $token");if(body!=null)b.method(method,body.toString().toRequestBody(json)) else b.method(method,null);client.newCall(b.build()).execute().use{r->val text=r.body?.string().orEmpty();if(!r.isSuccessful)error(try{JSONObject(text).optString("detail").ifBlank{"HTTP ${r.code}"}catch(_:Exception){"HTTP ${r.code}"});return text} }
    fun register(n:String,p:String,w:String)=JSONObject(request("/api/auth/register",body=JSONObject().put("name",n).put("phone",p).put("password",w),method="POST"))
    fun login(p:String,w:String)=JSONObject(request("/api/auth/login",body=JSONObject().put("phone",p).put("password",w),method="POST"))
    private fun array(path:String,t:String,key:String)=JSONObject(request(path,t)).getJSONArray(key).let{a->(0 until a.length()).map{a.getJSONObject(it)}}
    fun advanced(t:String,q:String,type:String,judge:String,from:String,to:String):List<JSONObject>{val p=mutableListOf<String>();if(q.isNotBlank())p+="q="+enc(q);p+="case_type="+enc(type);p+="judge="+enc(judge);if(from.isNotBlank())p+="session_from="+enc(from);if(to.isNotBlank())p+="session_to="+enc(to);p+="limit=50";return array("/api/cases/advanced-search?"+p.joinToString("&"),t,"cases")}
    fun sessions(t:String,d:String)=array("/api/sessions?date="+enc(d),t,"sessions")
    fun users(t:String,state:String):List<UserRow> = array("/api/admin/users/manage?state=$state&limit=200",t,"users").map{UserRow(it.optInt("id"),it.optString("name"),it.optString("phone"),it.optString("state"),it.optString("role"))}
    fun patchUser(t:String,id:Int,body:JSONObject){request("/api/admin/users/$id",t,body,"PATCH")}
    fun stats(t:String)=JSONObject(request("/api/admin/reports/stats",t))
    fun activity(t:String)=array("/api/admin/activity?limit=200",t,"events").map{val actor=it.optJSONObject("actor");EventRow(it.optString("action"),actor?.optString("name").orEmpty(),it.optString("created_at"),it.optJSONObject("metadata")?.toString().orEmpty())}
    fun pdf(t:String,number:String):ByteArray { val b=Request.Builder().url(url("/api/cases/pdf")).header("Authorization","Bearer $t").post(JSONObject().put("case_number",number).toString().toRequestBody(json));client.newCall(b.build()).execute().use{r->if(!r.isSuccessful)error("تعذر تنزيل PDF (${r.code})");return r.body?.bytes()?:error("ملف PDF فارغ") } }
    private fun enc(s:String)=URLEncoder.encode(s,"UTF-8")
}
