import java.util.concurrent.TimeUnit

private val Navy = Color(0xFF203D52)
private val Gold = Color(0xFFC9A044)
private val Muted = Color(0xFF77838A)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        window.statusBarColor = android.graphics.Color.WHITE
        window.navigationBarColor = android.graphics.Color.WHITE
        window.decorView.systemUiVisibility =
            View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR or View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR

        setContent {
            CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) {
                MaterialTheme(
                    colorScheme = lightColorScheme(
                        primary = Navy,
                        secondary = Gold,
                        background = Color.Transparent,
                        surface = Color.White
                    )
                ) {
                    CourtApp(::openPdf)
                }
            }
        }
    }

    private fun openPdf(fileName: String, pdfBytes: ByteArray) {
        val file = File(cacheDir, "case_${fileName.replace(Regex(\"[^A-Za-z0-9_-]\"), "_")}.pdf")
        file.writeBytes(pdfBytes)

        val authority = "$packageName.fileprovider"
        val uri: Uri = FileProvider.getUriForFile(this, authority, file)

        val intent = Intent(Intent.ACTION_VIEW).apply {
            setDataAndType(uri, "application/pdf")
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }

        startActivity(Intent.createChooser(intent, "فتح الملف"))
    }
}

@Composable
private fun CourtApp(openPdf: (String, ByteArray) -> Unit) {
    val scope = rememberCoroutineScope()
    var token by remember { mutableStateOf<String?>(null) }
    var currentPage by remember { mutableStateOf("auth") }
    var message by remember { mutableStateOf("") }
    var busy by remember { mutableStateOf(false) }

    // Login / register
    var registerMode by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }

    // Search
    var q by remember { mutableStateOf("") }
    var caseType by remember { mutableStateOf("all") }
    var judge by remember { mutableStateOf("all") }
    var fromDate by remember { mutableStateOf("") }
    var toDate by remember { mutableStateOf("") }
    var pdfCaseNumber by remember { mutableStateOf("") }
    var sessionDate by remember { mutableStateOf("") }

    var cases by remember { mutableStateOf(emptyList<JSONObject>()) }
    var sessions by remember { mutableStateOf(emptyList<JSONObject>()) }
    var users by remember { mutableStateOf(emptyList<UserItem>()) }
    var events by remember { mutableStateOf(emptyList<EventItem>()) }
    var stats by remember { mutableStateOf<JSONObject?>(null) }

    fun requestAsync(block: suspend () -> Unit) {
        if (busy) return
        busy = true
        message = ""
        scope.launch {
            try {
                withContext(Dispatchers.IO) {
                    block()
                }
            } catch (e: Exception) {
                message = e.message ?: "تعذر الاتصال بالخادم."
            } finally {
                busy = false
            }
        }
    }

    Surface(
        modifier = Modifier.fillMaxSize(),
        color = Color.Transparent
    ) {
        when (currentPage) {
            "auth" -> AuthScreen(
                registerMode = registerMode,
                name = name,
                phone = phone,
                password = password,
                busy = busy,
                message = message,
                onNameChange = { name = it },
                onPhoneChange = { phone = it },
                onPasswordChange = { password = it },
                onToggleMode = { registerMode = !registerMode },
                onSubmit = {
                    requestAsync {
                        if (registerMode) {
                            val result = Api.register(name, phone, password)
                            message = result.optString("message", "تم إرسال طلبك بنجاح.")
                            registerMode = false
                        } else {
                            val result = Api.login(phone, password)
                            val tokenValue = result.getString("access_token")
                            token = tokenValue
                            currentPage = "home"
                        }
                    }
                }
            )

            "home" -> HomeScreen(
                token = token ?: "",
                busy = busy,
                message = message,
                q = q,
                caseType = caseType,
                judge = judge,
                fromDate = fromDate,
                toDate = toDate,
                pdfCaseNumber = pdfCaseNumber,
                sessionDate = sessionDate,
                cases = cases,
                onQChange = { q = it },
                onCaseTypeChange = { caseType = it },
                onJudgeChange = { judge = it },
                onFromDateChange = { fromDate = it },
                onToDateChange = { toDate = it },
                onPdfCaseNumberChange = { pdfCaseNumber = it },
                onSessionDateChange = { sessionDate = it },
                onSearchCases = {
                    requestAsync {
                        val result = Api.advancedSearch(token ?: "", q, caseType, judge, fromDate, toDate)
                        cases = result
                    }
                },
                onOpenPdf = {
                    requestAsync {
                        val bytes = Api.downloadPdf(token ?: "", pdfCaseNumber)
                        openPdf(pdfCaseNumber, bytes)
                    }
                },
                onOpenSessions = { currentPage = "sessions" },
                onOpenAdmin = { currentPage = "admin" },
                onLogout = {
                    token = null
                    currentPage = "auth"
                },
                onViewCases = {
                    requestAsync {
                        val result = Api.advancedSearch(token ?: "", q, caseType, judge, fromDate, toDate)
                        cases = result
                    }
                }
            )

            "sessions" -> SessionsScreen(
                token = token ?: "",
                busy = busy,
                message = message,
                sessionDate = sessionDate,
                sessions = sessions,
                onDateChange = { sessionDate = it },
                onSearch = {
                    requestAsync {
                        val result = Api.sessions(token ?: "", sessionDate)
                        sessions = result
                    }
                },
                onBack = { currentPage = "home" }
            )

            "admin" -> AdminScreen(
                token = token ?: "",
                busy = busy,
                message = message,
                users = users,
                events = events,
                stats = stats,
                onLoadUsers = {
                    requestAsync {
                        users = Api.listUsers(token ?: "", "all")
                    }
                },
                onLoadPending = {
                    requestAsync {
                        users = Api.listUsers(token ?: "", "pending")
                    }
                },
                onLoadStats = {
                    requestAsync {
                        stats = Api.stats(token ?: "")
                    }
                },
                onLoadActivity = {
                    requestAsync {
                        events = Api.activity(token ?: "")
                    }
                },
                onApproveUser = { userId ->
                    requestAsync {
                        Api.patchUser(token ?: "", userId, JSONObject().put("state", "approved"))
                        users = Api.listUsers(token ?: "", "all")
                    }
                },
                onRejectUser = { userId ->
                    requestAsync {
                        Api.patchUser(token ?: "", userId, JSONObject().put("state", "rejected"))
                        users = Api.listUsers(token ?: "", "all")
                    }
                },
                onBack = { currentPage = "home" }
            )
        }
    }
}

