private data class UserItem(
    val id: Int,
    val name: String,
    val phone: String,
    val role: String,
    val state: String
)

private data class EventItem(
    val action: String,
    val actor: String,
    val date: String,
    val meta: String
)

private object Api {
    private val client = OkHttpClient.Builder()
        .connectTimeout(15, TimeUnit.SECONDS)
        .readTimeout(45, TimeUnit.SECONDS)
        .build()

    private val jsonType = "application/json; charset=utf-8".toMediaType()

    private fun baseUrl() = BuildConfig.API_BASE_URL.trimEnd('/')

    private fun encode(value: String) = URLEncoder.encode(value, "UTF-8")

    private fun requestJson(path: String, token: String? = null, method: String = "GET", body: JSONObject? = null): JSONObject {
        val requestBuilder = Request.Builder()
            .url(baseUrl() + path)
            .header("Accept", "application/json")

        if (token.isNotBlank()) {
            requestBuilder.header("Authorization", "Bearer $token")
        }

        if (body != null) {
            requestBuilder.method(method, body.toString().toRequestBody(jsonType))
        } else {
            requestBuilder.method(method, null)
        }

        return client.newCall(requestBuilder.build()).execute().use { response ->
            val raw = response.body?.string().orEmpty()
            if (!response.isSuccessful) {
                throw IllegalStateException(
                    try {
                        JSONObject(raw).optString("detail", "HTTP ${response.code}")
                    } catch (_: Exception) {
                        "HTTP ${response.code}"
                    }
                )
            }
            if (raw.isBlank()) {
                return JSONObject()
            }
            return JSONObject(raw)
        }
    }

    fun register(name: String, phone: String, password: String): JSONObject {
        return requestJson(
            "/api/auth/register",
            method = "POST",
            body = JSONObject()
                .put("name", name)
                .put("phone", phone)
                .put("password", password)
        )
    }

    fun login(phone: String, password: String): JSONObject {
        return requestJson(
            "/api/auth/login",
            method = "POST",
            body = JSONObject()
                .put("phone", phone)
                .put("password", password)
        )
    }

    fun advancedSearch(token: String, q: String, caseType: String, judge: String, fromDate: String, toDate: String): List<JSONObject> {
        val params = buildString {
            append("limit=50")
            if (q.isNotBlank()) append("&q=${encode(q)}")
            if (caseType.isNotBlank() && caseType != "all") append("&case_type=${encode(caseType)}")
            if (judge.isNotBlank() && judge != "all") append("&judge=${encode(judge)}")
            if (fromDate.isNotBlank()) append("&session_from=${encode(fromDate)}")
            if (toDate.isNotBlank()) append("&session_to=${encode(toDate)}")
        }
        val response = requestJson("/api/cases/advanced-search?$params", token = token)
        val arr = response.optJSONArray("cases") ?: return emptyList()
        return (0 until arr.length()).map { arr.getJSONObject(it) }
    }

    fun sessions(token: String, date: String): List<JSONObject> {
        val response = requestJson("/api/sessions?date=${encode(date)}", token = token)
        val arr = response.optJSONArray("sessions") ?: return emptyList()
        return (0 until arr.length()).map { arr.getJSONObject(it) }
    }

    fun listUsers(token: String, state: String): List<UserItem> {
        val response = requestJson("/api/admin/users/manage?state=${encode(state)}&limit=200", token = token)
        val arr = response.optJSONArray("users") ?: return emptyList()
        return (0 until arr.length()).map { item ->
            val obj = item as JSONObject
            UserItem(
                id = obj.optInt("id"),
                name = obj.optString("name"),
                phone = obj.optString("phone"),
                role = obj.optString("role"),
                state = obj.optString("state")
            )
        }
    }

    fun patchUser(token: String, userId: Int, data: JSONObject) {
        requestJson("/api/admin/users/$userId", token = token, method = "PATCH", body = data)
    }

    fun stats(token: String): JSONObject {
        val response = requestJson("/api/admin/reports/stats", token = token)
        return response
    }

    fun activity(token: String): List<EventItem> {
        val response = requestJson("/api/admin/activity?limit=200", token = token)
        val arr = response.optJSONArray("events") ?: return emptyList()
        return (0 until arr.length()).map { item ->
            val obj = item as JSONObject
            EventItem(
                action = obj.optString("action"),
                actor = obj.optString("actor")?.let { actor ->
                    val actorObj = obj.optJSONObject("actor")
                    actorObj?.optString("name") ?: "غير معروف"
                } ?: "غير معروف",
                date = obj.optString("created_at"),
                meta = obj.optJSONObject("metadata")?.toString() ?: ""
            )
        }
    }

    fun downloadPdf(token: String, caseNumber: String): ByteArray {
        val response = requestJson("/api/cases/pdf?case_number=${encode(caseNumber)}", token)
        val bytes = response.opt("pdf") ?: return ByteArray(0)
        return (bytes as? ByteArray) ?: bytes.toString().toByteArray()
    }
}
