## 2. نماذج وواجهات API — `CourtApi.kt`

```kotlin name=android/app/src/main/java/org/albayda/court/CourtApi.kt
package org.albayda.court

import com.google.gson.JsonObject
import okhttp3.ResponseBody
import retrofit2.Response
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import retrofit2.http.*

data class Credentials(val phone: String, val password: String)
data class RegisterRequest(val name: String, val phone: String, val password: String)
data class UserDto(
    val id: Int,
    val name: String,
    val phone: String,
    val role: String,
    val state: String,
    @com.google.gson.annotations.SerializedName("created_at") val createdAt: String = ""
)
data class LoginResponse(
    @com.google.gson.annotations.SerializedName("access_token") val accessToken: String,
    val user: UserDto
)
data class RegisterResponse(val state: String, val message: String)
data class UsersResponse(val total: Int, val users: List<UserDto>)
data class CasesResponse(val count: Int, val cases: List<Map<String, String?>>)
data class SessionsResponse(val count: Int, val sessions: List<Map<String, String?>>)
data class ActivityResponse(val events: List<ActivityDto>)
data class ActivityDto(
    val id: Int,
    val action: String,
    val actor: ActorDto?,
    val metadata: JsonObject?,
    @com.google.gson.annotations.SerializedName("created_at") val createdAt: String
)
data class ActorDto(val name: String?, val phone: String?)
data class DecisionRequest(val approve: Boolean)

interface CourtApi {
    @POST("api/auth/login")
    suspend fun login(@Body body: Credentials): Response<LoginResponse>

    @POST("api/auth/register")
    suspend fun register(@Body body: RegisterRequest): Response<RegisterResponse>

    @GET("api/cases/advanced-search")
    suspend fun searchCases(
        @Header("Authorization") bearer: String,
        @Query("q") query: String?,
        @Query("case_type") caseType: String,
        @Query("judge") judge: String,
        @Query("session_from") fromDate: String?,
        @Query("session_to") toDate: String?,
        @Query("limit") limit: Int = 50
    ): Response<CasesResponse>

    @GET("api/sessions")
    suspend fun sessions(
        @Header("Authorization") bearer: String,
        @Query("date") date: String
    ): Response<SessionsResponse>

    @GET("api/admin/users/manage")
    suspend fun users(
        @Header("Authorization") bearer: String,
        @Query("state") state: String = "all",
        @Query("q") query: String = "",
        @Query("limit") limit: Int = 100,
        @Query("offset") offset: Int = 0
    ): Response<UsersResponse>

    @PATCH("api/admin/users/{id}")
    suspend fun updateUser(
        @Header("Authorization") bearer: String,
        @Path("id") id: Int,
        @Body fields: Map<String, String>
    ): Response<JsonObject>

    @DELETE("api/admin/users/{id}")
    suspend fun deactivateUser(
        @Header("Authorization") bearer: String,
        @Path("id") id: Int
    ): Response<JsonObject>

    @GET("api/admin/reports/stats")
    suspend fun statistics(
        @Header("Authorization") bearer: String
    ): Response<JsonObject>

    @GET("api/admin/activity")
    suspend fun activity(
        @Header("Authorization") bearer: String,
        @Query("limit") limit: Int = 100,
        @Query("offset") offset: Int = 0
    ): Response<ActivityResponse>

    @Streaming
    @POST("api/cases/pdf")
    suspend fun casePdf(
        @Header("Authorization") bearer: String,
        @Body body: Map<String, String>
    ): Response<ResponseBody>
}

object ApiProvider {
    val api: CourtApi by lazy {
        val base = BuildConfig.API_BASE_URL.trim()
        require(base.startsWith("https://") && !base.contains("configure-api-url.invalid")) {
            "اضبط API_BASE_URL على عنوان الخادم الحقيقي باستخدام HTTPS."
        }
        Retrofit.Builder()
            .baseUrl(if (base.endsWith("/")) base else "$base/")
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(CourtApi::class.java)
    }
}
```

## 3. التطبيق وشاشاته — `MainActivity.kt`

هذا الهيكل يفصل المصادقة والبحث والجلسات والإدارة والتقارير وسجل النشاط إلى شاشات Compose مستقلة. خلفية الصفحات شفافة، مع بطاقات مقروءة.

```kotlin name=android/app/src/main/java/org/albayda/court/MainActivity.kt
package org.albayda.court

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.platform.LocalLayoutDirection
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.PasswordVisualTransformation
import androidx.compose.ui.unit.LayoutDirection
import androidx.compose.ui.unit.dp
import androidx.core.content.FileProvider
import kotlinx.coroutines.launch
import okhttp3.ResponseBody
import retrofit2.Response
import java.io.File

private enum class Screen { AUTH, HOME, SEARCH, SESSIONS, ADMIN, USERS, REPORTS, ACTIVITY }
private val Navy = Color(0xFF203D52)
private val Gold = Color(0xFFC9A044)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) {
                MaterialTheme(colorScheme = lightColorScheme(primary = Navy, secondary = Gold)) {
                    CourtApplication()
                }
            }
        }
    }
}

@Composable
private fun CourtApplication() {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val api = remember { ApiProvider.api }

    var screen by remember { mutableStateOf(Screen.AUTH) }
    var token by remember { mutableStateOf("") }
    var role by remember { mutableStateOf("") }
    var busy by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf("") }

    var cases by remember { mutableStateOf(emptyList<Map<String, String?>>()) }
    var sessions by remember { mutableStateOf(emptyList<Map<String, String?>>()) }
    var users by remember { mutableStateOf(emptyList<UserDto>()) }
    var events by remember { mutableStateOf(emptyList<ActivityDto>()) }
    var stats by remember { mutableStateOf("") }

    fun runRequest(block: suspend () -> Unit) {
        if (busy) return
        busy = true
        message = ""
        scope.launch {
            try { block() }
            catch (e: Exception) { message = e.message ?: "تعذر تنفيذ الطلب." }
            finally { busy = false }
        }
    }

    Surface(Modifier.fillMaxSize(), color = Color.Transparent) {
        when (screen) {
            Screen.AUTH -> AuthScreen(busy, message, onLogin = { phone, password ->
                runRequest {
                    val response = api.login(Credentials(phone, password))
                    if (!response.isSuccessful) error(response.errorBody()?.string() ?: "تعذر تسجيل الدخول")
                    val data = response.body() ?: error("استجابة الخادم فارغة")
                    token = data.accessToken
                    role = data.user.role
                    screen = Screen.HOME
                }
            }, onRegister = { name, phone, password ->
                runRequest {
                    val response = api.register(RegisterRequest(name, phone, password))
                    if (!response.isSuccessful) error(response.errorBody()?.string() ?: "تعذر إنشاء الحساب")
                    message = response.body()?.message ?: "تم إرسال طلب التسجيل للمراجعة."
                }
            })

            Screen.HOME -> HomeScreen(role, busy, message,
                onSearch = { screen = Screen.SEARCH },
                onSessions = { screen = Screen.SESSIONS },
                onAdmin = { if (role == "admin") screen = Screen.ADMIN else message = "هذه الشاشة للمدير فقط." },
                onLogout = { token = ""; role = ""; screen = Screen.AUTH }
            )

            Screen.SEARCH -> SearchScreen(busy, message, cases, onBack = { screen = Screen.HOME }, onSearch = { q, type, judge, from, to ->
                runRequest {
                    val response = api.searchCases("Bearer $token", q.ifBlank { null }, type, judge, from.ifBlank { null }, to.ifBlank { null })
                    if (!response.isSuccessful) error(response.errorBody()?.string() ?: "فشل البحث")
                    cases = response.body()?.cases.orEmpty()
                }
            }, onPdf = { caseNumber ->
                runRequest {
                    val response = api.casePdf("Bearer $token", mapOf("case_number" to caseNumber))
                    if (!response.isSuccessful) error(response.errorBody()?.string() ?: "تعذر إنشاء PDF")
                    val bytes = response.body()?.bytes() ?: error("ملف PDF فارغ")
                    val file = File(context.cacheDir, "case_${caseNumber.filter { it.isLetterOrDigit() || it == '-' || it == '_' }}.pdf")
                    file.writeBytes(bytes)
                    val uri: Uri = FileProvider.getUriForFile(context, "${context.packageName}.fileprovider", file)
                    val intent = Intent(Intent.ACTION_VIEW).setDataAndType(uri, "application/pdf")
                        .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    context.startActivity(Intent.createChooser(intent, context.getString(R.string.open_pdf)))
                }
            })

            Screen.SESSIONS -> SessionsScreen(busy, message, sessions, onBack = { screen = Screen.HOME }, onSearch = { date ->
                runRequest {
                    val response = api.sessions("Bearer $token", date)
                    if (!response.isSuccessful) error(response.errorBody()?.string() ?: "فشل البحث عن الجلسات")
                    sessions = response.body()?.sessions.orEmpty()
                }
            })

            Screen.ADMIN -> AdminScreen(onBack = { screen = Screen.HOME },
                onUsers = { screen = Screen.USERS }, onReports = { screen = Screen.REPORTS },
                onActivity = { screen = Screen.ACTIVITY })

            Screen.USERS -> UsersScreen(busy, message, users, onBack = { screen = Screen.ADMIN },
                onLoad = { state, query ->
                    runRequest {
                        val response = api.users("Bearer $token", state, query)
                        if (!response.isSuccessful) error(response.errorBody()?.string() ?: "فشل تحميل المستخدمين")
                        users = response.body()?.users.orEmpty()
                    }
                }, onApprove = { user ->
                    runRequest {
                        val response = api.updateUser("Bearer $token", user.id, mapOf("state" to "approved"))
                        if (!response.isSuccessful) error("تعذر اعتماد الحساب")
                        users = api.users("Bearer $token", "all").body()?.users.orEmpty()
                    }
                }, onDeactivate = { user ->
                    runRequest {
                        val response = api.deactivateUser("Bearer $token", user.id)
                        if (!response.isSuccessful) error("تعذر إيقاف الحساب")
                        users = api.users("Bearer $token", "all").body()?.users.orEmpty()
                    }
                })

            Screen.REPORTS -> ReportsScreen(busy, message, stats, onBack = { screen = Screen.ADMIN }, onLoad = {
                runRequest {
                    val response = api.statistics("Bearer $token")
                    if (!response.isSuccessful) error("تعذر تحميل الإحصاءات")
                    stats = response.body()?.toString() ?: "{}"
                }
            })

            Screen.ACTIVITY -> ActivityScreen(busy, message, events, onBack = { screen = Screen.ADMIN }, onLoad = {
                runRequest {
                    val response = api.activity("Bearer $token")
                    if (!response.isSuccessful) error("تعذر تحميل سجل النشاط")
                    events = response.body()?.events.orEmpty()
                }
            })
        }
    }
}

@Composable
private fun AuthScreen(busy: Boolean, message: String, onLogin: (String, String) -> Unit, onRegister: (String, String, String) -> Unit) {
    var register by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.Center) {
        Text(stringResource(R.string.app_name), style = MaterialTheme.typography.headlineMedium, color = Navy, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(16.dp))
        Card { Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            if (register) OutlinedTextField(name, { name = it }, label = { Text(stringResource(R.string.full_name)) }, modifier = Modifier.fillMaxWidth())
            OutlinedTextField(phone, { phone = it }, label = { Text(stringResource(R.string.phone)) }, modifier = Modifier.fillMaxWidth())
            OutlinedTextField(password, { password = it }, label = { Text(stringResource(R.string.password)) }, visualTransformation = PasswordVisualTransformation(), modifier = Modifier.fillMaxWidth())
            Button(enabled = !busy, onClick = {
                if (register) onRegister(name.trim(), phone.trim(), password)
                else onLogin(phone.trim(), password)
            }, modifier = Modifier.fillMaxWidth()) { Text(if (busy) stringResource(R.string.loading) else if (register) stringResource(R.string.register) else stringResource(R.string.login)) }
            TextButton(onClick = { register = !register }) { Text(stringResource(if (register) R.string.have_account else R.string.create_account)) }
        } }
        if (message.isNotBlank()) Text(message, Modifier.padding(top = 12.dp), color = Navy)
    }
}

@Composable
private fun HomeScreen(role: String, busy: Boolean, message: String, onSearch: () -> Unit, onSessions: () -> Unit, onAdmin: () -> Unit, onLogout: () -> Unit) {
    Column(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Text(stringResource(R.string.home_title), style = MaterialTheme.typography.headlineSmall, color = Navy)
        Button(onClick = onSearch, modifier = Modifier.fillMaxWidth()) { Text(stringResource(R.string.advanced_search)) }
        Button(onClick = onSessions, modifier = Modifier.fillMaxWidth()) { Text(stringResource(R.string.daily_sessions)) }
        if (role == "admin") Button(onClick = onAdmin, modifier = Modifier.fillMaxWidth()) { Text(stringResource(R.string.admin)) }
        TextButton(onClick = onLogout) { Text(stringResource(R.string.logout)) }
        if (message.isNotBlank()) Text(message)
    }
}

@Composable
private fun SearchScreen(
    busy: Boolean, message: String, cases: List<Map<String, String?>>,
    onBack: () -> Unit, onSearch: (String, String, String, String, String) -> Unit, onPdf: (String) -> Unit
) {
    var query by remember { mutableStateOf("") }
    var type by remember { mutableStateOf("all") }
    var judge by remember { mutableStateOf("all") }
    var from by remember { mutableStateOf("") }
    var to by remember { mutableStateOf("") }
    var pdfNumber by remember { mutableStateOf("") }

    Column(Modifier.fillMaxSize().padding(16.dp)) {
        ScreenHeader(stringResource(R.string.advanced_search), onBack)
        OutlinedTextField(query, { query = it }, label = { Text(stringResource(R.string.query)) }, modifier = Modifier.fillMaxWidth())
        OutlinedTextField(type, { type = it }, label = { Text(stringResource(R.string.case_type_all)) }, modifier = Modifier.fillMaxWidth())
        OutlinedTextField(judge, { judge = it }, label = { Text(stringResource(R.string.judge_all)) }, modifier = Modifier.fillMaxWidth())
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedTextField(from, { from = it }, label = { Text(stringResource(R.string.from_date)) }, modifier = Modifier.weight(1f))
            OutlinedTextField(to, { to = it }, label = { Text(stringResource(R.string.to_date)) }, modifier = Modifier.weight(1f))
        }
        Button(enabled = !busy, onClick = { onSearch(query, type, judge, from, to) }, modifier = Modifier.fillMaxWidth()) {
            Text(if (busy) stringResource(R.string.loading) else stringResource(R.string.search))
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedTextField(pdfNumber, { pdfNumber = it }, label = { Text(stringResource(R.string.case_number)) }, modifier = Modifier.weight(1f))
            Button(enabled = !busy && pdfNumber.isNotBlank(), onClick = { onPdf(pdfNumber) }) { Text(stringResource(R.string.pdf)) }
        }
        if (message.isNotBlank()) Text(message)
        LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            items(cases) { record -> RecordCard(record) }
        }
    }
}

