    Column(Modifier.fillMaxSize().padding(16.dp)) {
        ScreenHeader(stringResource(R.string.activity_log), onBack)
        Button(enabled = !busy, onClick = onLoad) { Text(stringResource(R.string.load)) }
        if (message.isNotBlank()) Text(message)
        LazyColumn { items(events, key = { it.id }) { event ->
            Card(Modifier.fillMaxWidth().padding(vertical = 4.dp)) {
                Column(Modifier.padding(12.dp)) {
                    Text(event.action, fontWeight = FontWeight.Bold)
                    Text(event.actor?.name ?: stringResource(R.string.system_event))
                    Text(event.createdAt)
                    event.metadata?.let { Text(it.toString()) }
                }
            }
        } }
    }
