@Composable
private fun RecordCard(record: Map<String, String?>) {
    Card(Modifier.fillMaxWidth().padding(vertical = 4.dp)) {
        Column(Modifier.padding(12.dp)) {
            Text(record["رقم القضية"].orEmpty(), fontWeight = FontWeight.Bold, color = Navy)
            listOf("نوع القضية", "المدعي", "المدعى عليه", "برئاسة القاضي", "الجلسة القادمة", "موضوعها")
                .forEach { key -> record[key]?.takeIf(String::isNotBlank)?.let { Text("$key: $it") } }
        }
    }
}

@Composable
private fun ScreenHeader(title: String, onBack: () -> Unit) {
    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
        Text(title, style = MaterialTheme.typography.titleLarge, color = Navy)
        TextButton(onClick = onBack) { Text(stringResource(R.string.back)) }
    }
}

