from __future__ import annotations

import json
import logging
import os
import re
import sqlite3
import unicodedata
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Annotated

import jwt
from argon2 import PasswordHasher
from argon2.exceptions import InvalidHashError, VerifyMismatchError
from dotenv import load_dotenv
from fastapi import Depends, FastAPI, HTTPException, Query, Request, Response, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from pydantic import BaseModel, Field

from case_records import (
    CaseRecordsError,
    available_case_types,
    available_judges,
    generate_case_pdf,
    load_case_records,
    normalize_judge_name,
    search_case_records,
    search_sessions_by_date,
)

load_dotenv()
logging.basicConfig(level=os.getenv("LOG_LEVEL", "INFO"))
LOG = logging.getLogger("albayda_api")

APP_DIR = Path(__file__).resolve().parent
DB_PATH = Path(os.getenv("APP_DATABASE_PATH", str(APP_DIR / "data" / "app.sqlite3")))
JWT_SECRET = os.getenv("JWT_SECRET", "")
HASHER = PasswordHasher()
BEARER = HTTPBearer(auto_error=False)

app = FastAPI(
    title="Albayda Court API",
    version="1.0.0",
    description="Private API for Albayda Court Android app",
    docs_url=None,
    redoc_url=None,
)

class RegisterBody(BaseModel):
    name: str = Field(min_length=2, max_length=120)
    phone: str = Field(min_length=7, max_length=24)
    password: str = Field(min_length=10, max_length=128)

class LoginBody(BaseModel):
    phone: str = Field(min_length=7, max_length=24)
    password: str = Field(min_length=1, max_length=128)

class DecisionBody(BaseModel):
    approve: bool

def now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

@contextmanager
def db():
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(DB_PATH, timeout=20)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

def normalize_phone(value: str) -> str:
    chars = []
    for char in value.strip():
        if char.isdecimal():
            chars.append(str(unicodedata.decimal(char)))
        elif char == "+" and not chars:
            chars.append(char)
        elif char in " -().":
            continue
        else:
            raise HTTPException(status_code=422, detail="رقم الجوال غير صالح.")
    result = "".join(chars)
    digits = result[1:] if result.startswith("+") else result
    if not digits.isdigit() or not 7 <= len(digits) <= 15:
        raise HTTPException(status_code=422, detail="رقم الجوال غير صالح.")
    return result

def audit(actor_id: int | None, action: str, metadata=None, target_id: int | None = None):
    with db() as conn:
        conn.execute(
            "INSERT INTO activity(actor_id, action, target_id, metadata, created_at) VALUES (?, ?, ?, ?, ?)",
            (actor_id, action, target_id, json.dumps(metadata or {}, ensure_ascii=False), now()),
        )

def initialize_db():
    with db() as conn:
        conn.executescript("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                phone TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'user',
                state TEXT NOT NULL DEFAULT 'pending',
                created_at TEXT NOT NULL,
                reviewed_at TEXT,
                reviewed_by INTEGER REFERENCES users(id)
            );

            CREATE TABLE IF NOT EXISTS activity (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                actor_id INTEGER REFERENCES users(id),
                action TEXT NOT NULL,
                target_id INTEGER REFERENCES users(id),
                metadata TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL
            );

            CREATE INDEX IF NOT EXISTS idx_users_state ON users(state, created_at);
            CREATE INDEX IF NOT EXISTS idx_activity_created ON activity(created_at DESC);
        """)

        admin_exists = conn.execute("SELECT 1 FROM users WHERE role='admin' LIMIT 1").fetchone()
        if admin_exists is None:
            admin_name = os.getenv("ADMIN_BOOTSTRAP_NAME", "").strip()
            admin_phone = os.getenv("ADMIN_BOOTSTRAP_PHONE", "").strip()
            admin_password = os.getenv("ADMIN_BOOTSTRAP_PASSWORD", "")

            if not (admin_name and admin_phone and len(admin_password) >= 12):
                raise RuntimeError(
                    "Set ADMIN_BOOTSTRAP_NAME, ADMIN_BOOTSTRAP_PHONE, and ADMIN_BOOTSTRAP_PASSWORD "
                    "with at least 12 characters."
                )

            conn.execute(
                "INSERT INTO users(name, phone, password_hash, role, state, created_at) VALUES (?, ?, ?, 'admin', 'approved', ?)",
                (admin_name, normalize_phone(admin_phone), HASHER.hash(admin_password), now()),
            )

            LOG.info("Initial admin account created successfully.")

@app.on_event("startup")
def startup():
    if len(JWT_SECRET) < 32:
        raise RuntimeError("JWT_SECRET must be at least 32 random chars.")
    initialize_db()

@app.middleware("http")
async def security_headers(request: Request, call_next):
    response = await call_next(request)
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    return response

def current_user(credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(BEARER)]):
    if credentials is None:
        raise HTTPException(status_code=401, detail="سجّل الدخول للمتابعة.", headers={"WWW-Authenticate": "Bearer"})
    try:
        payload = jwt.decode(
            credentials.credentials,
            JWT_SECRET,
            algorithms=["HS256"],
            options={"require": ["sub", "exp"]},
        )
        user_id = int(payload["sub"])
    except Exception:
        raise HTTPException(status_code=401, detail="انتهت صلاحية الجلسة؛ سجّل الدخول مجدداً.")

    with db() as conn:
        user = conn.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone()

    if user is None:
        raise HTTPException(status_code=401, detail="الحساب غير موجود.")
    if user["state"] != "approved":
        raise HTTPException(status_code=403, detail="الحساب غير معتمد أو تم إيقافه.")

    return dict(user)

def admin_user(user: Annotated[dict, Depends(current_user)]):
    if user["role"] != "admin":
        raise HTTPException(status_code=403, detail="هذه العملية للمسؤول فقط.")
    return user

def public_user(row):
    return {
        "id": row["id"],
        "name": row["name"],
        "phone": row["phone"],
        "role": row["role"],
        "state": row["state"],
        "created_at": row["created_at"],
    }

def issue_token(user):
    now_ts = int(datetime.now(timezone.utc).timestamp())
    return jwt.encode(
        {"sub": str(user["id"]), "iat": now_ts, "exp": now_ts + 8 * 60 * 60},
        JWT_SECRET,
        algorithm="HS256",
    )

