package org.albayda.court

import com.google.gson.JsonObject
import okhttp3.ResponseBody
import retrofit2.Response
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import retrofit2.http.*

data class Credentials(val phone: String, val password: String)
data class RegisterRequest(val name: String, val phone: String, val password: String)
data class UserDto(
    val id: Int,
    val name: String,
    val phone: String,
    val role: String,
    val state: String,
    @com.google.gson.annotations.SerializedName("created_at") val createdAt: String = ""
)
data class LoginResponse(
    @com.google.gson.annotations.SerializedName("access_token") val accessToken: String,
    val user: UserDto
)
data class RegisterResponse(val state: String, val message: String)
data class UsersResponse(val total: Int, val users: List<UserDto>)
data class CasesResponse(val count: Int, val cases: List<Map<String, String?>>)
data class SessionsResponse(val count: Int, val sessions: List<Map<String, String?>>)
data class ActivityResponse(val events: List<ActivityDto>)
data class ActivityDto(
    val id: Int,
    val action: String,
    val actor: ActorDto?,
    val metadata: JsonObject?,
    @com.google.gson.annotations.SerializedName("created_at") val createdAt: String
)
data class ActorDto(val name: String?, val phone: String?)
data class DecisionRequest(val approve: Boolean)

interface CourtApi {
    @POST("api/auth/login")
    suspend fun login(@Body body: Credentials): Response<LoginResponse>

    @POST("api/auth/register")
    suspend fun register(@Body body: RegisterRequest): Response<RegisterResponse>

    @GET("api/cases/advanced-search")
    suspend fun searchCases(
        @Header("Authorization") bearer: String,
        @Query("q") query: String?,
        @Query("case_type") caseType: String,
        @Query("judge") judge: String,
        @Query("session_from") fromDate: String?,
        @Query("session_to") toDate: String?,
        @Query("limit") limit: Int = 50
    ): Response<CasesResponse>

    @GET("api/sessions")
    suspend fun sessions(
        @Header("Authorization") bearer: String,
        @Query("date") date: String
    ): Response<SessionsResponse>

    @GET("api/admin/users/manage")
    suspend fun users(
        @Header("Authorization") bearer: String,
        @Query("state") state: String = "all",
        @Query("q") query: String = "",
        @Query("limit") limit: Int = 100,
        @Query("offset") offset: Int = 0
    ): Response<UsersResponse>

    @PATCH("api/admin/users/{id}")
    suspend fun updateUser(
        @Header("Authorization") bearer: String,
        @Path("id") id: Int,
        @Body fields: Map<String, String>
    ): Response<JsonObject>

    @DELETE("api/admin/users/{id}")
    suspend fun deactivateUser(
        @Header("Authorization") bearer: String,
        @Path("id") id: Int
    ): Response<JsonObject>

    @GET("api/admin/reports/stats")
    suspend fun statistics(
        @Header("Authorization") bearer: String
    ): Response<JsonObject>

    @GET("api/admin/activity")
    suspend fun activity(
        @Header("Authorization") bearer: String,
        @Query("limit") limit: Int = 100,
        @Query("offset") offset: Int = 0
    ): Response<ActivityResponse>

    @Streaming
    @POST("api/cases/pdf")
    suspend fun casePdf(
        @Header("Authorization") bearer: String,
        @Body body: Map<String, String>
    ): Response<ResponseBody>
}

object ApiProvider {
    val api: CourtApi by lazy {
        val base = BuildConfig.API_BASE_URL.trim()
        require(base.startsWith("https://") && !base.contains("configure-api-url.invalid")) {
            "اضبط API_BASE_URL على عنوان الخادم الحقيقي باستخدام HTTPS."
        }
        Retrofit.Builder()
            .baseUrl(if (base.endsWith("/")) base else "$base/")
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(CourtApi::class.java)
    }
}
